  Activity_116470_ActivityName = {
    Text = "极昼的终夜"
  },
  Activity_116470_ActivityPlot = {
    Text = "他们在命运的尽头擦肩而过，重新摆动的钟表已然迟到太久，只有那颗悔恨的心，发誓要将所有黑暗中的污秽全部照彻。"
