  Activity_116765_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「铭刻的启程」中领取奖励。\n2、解锁「高级纪行」后，完成任务后可额外领取奖励。\n3、本次「高级纪行」购买有时间限制，逾期将无法再购买。请守密人在 11 月 3日9：00前酌情购买。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_116765_BannerText = {
    Text = "特别纪行活动限时开启！"
