  Activity_119693_ActivityTips = {
    Text = "<Title:活动规则>\n·活动期间，每位守密人累计使用 200 次钥令后，可以从 8 名限定SSR唤醒体中选择 1 名唤醒，包括熔毁·朵尔、克莱门汀、克珀珊特、卡斯托尔、杜勒赛因、凯蒂古拉、皮克曼、波吕克斯。\n·当守密人选择已唤醒的唤醒体时，第 2~16 次获得相同SSR唤醒体时，每次将转换为 1 个对应唤醒体的残片和 「根源沉淀」× 50；第 17 次及之后获得，限定SSR唤醒体将转换为「精粹灵核碎片」× 2、「灵核碎片」× 6 和「根源沉淀」× 250。"
