  Activity_122195_ActivityName = {
    Text = "雾境的燔礼"
  },
  Activity_122195_ActivityPlot = {
    Text = "黎明的光正消解虔者之苦，繁星作舟，将兄弟姐妹载至高悬的国度。\n迷失的羔羊在门中歌舞，星烛装点着永恒的神庭。\n可门后的迷雾早已应呼唤而来，那迷雾欺瞒、诡骗，只为满足自己扭曲的趣味。\n那迷雾为此将「黎明」封锁，阻绝了尝试解脱的路。\n她将在此，见证世界的又一次尽头。"
  },
