  Activity_124801_ActivityPlot = {
    Text = "“我要让所有人都玩万象牌！”\n其他时空的来客因为一场意外进入了相位对弈的空间，将其改造成了与原先大不相同的样子。\n为了将空间再次逆转，不同时空的守密人将要决出一位最强者，向这名来客发起挑战。"
