  Activity_124834_ActivityPlot = {
    Text = "忘却前夜 × 雾境序列\n联动特别邀约\n\n「茉夏，调查团……哦不，现在已经不是调查团前锋了。那么，我再重新介绍一下自己——我叫茉夏，只是一个可爱的女孩子~」"
  },
  Activity_124834_ActivityTips = {
    Text = "<Title:活动规则>\n·在「因雾之名」活动期间完成调查行动第一章「东区秘事」后，可以免费获得全新限定SSR唤醒体「茉夏」！\n·当第 2~16 次获得相同SSR唤醒体时，每次将转换为 1 个对应唤醒体的残片和 「根源沉淀」× 50；第 17 次及之后获得，限定SSR唤醒体将转换为「精粹灵核碎片」× 2、「灵核碎片」× 6 和「根源沉淀」× 250。"
