  Activity_124987_ActivityName = {
    Text = "多重疗愈·复刻"
  },
  Activity_124987_ActivityPlot = {
    Text = "Hysteria，又名歇斯底里症、癔症。\n在你们身处的年代，它与死亡同义。\n\n幸运的是，弥萨格的科学家和调查员同样疯狂：他们决心攻克这一难题。"
