  Activity_124987_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「人格解析」"
  },
  Activity_124987_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「记忆编码」、「边缘存储」和「成就奖励」收集活动货币「记忆拼图」，「记忆拼图」可在「人格解析」中购买商品，包括活动限定SR命轮「银鳕鱼的决心」、流明之芯、无垢之芯等。\n2、活动期间，「特遣纪录：宁静的裂殖」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：「24」」！\n\n<Title:活动时间>\n1、2 月 23 日 9:00 - 3 月 9 日 9:00（GMT+8），所有活动玩法均可参与。\n2、3 月 9 日 9:00 - 3 月 16 日 9:00（GMT+8），仅可参与「人格解析」和成就奖励。\n\n<Title:记忆编码>\n1、「记忆编码」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：分离性症候」来帮助你更轻松地过关。\n\n<Title:理性加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「记忆编码」关卡任务报酬中的「记忆拼图」获得额外的掉落加成，具体加成如下：\n·唤醒体「24」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「畸体回噬」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「银鳕鱼的决心」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「理性加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「理性加成」影响。\n\n<Title:共鸣：分离性症候>\n1、守密人可以通过完成活动成就获取「分裂之心」。 \n2、消耗「分裂之心」，激活「共鸣：分离性症候」，可以获得以下加成：\n（1）让守密人在活动玩法「记忆编码」和「特遣纪录：宁静的裂殖」中变得更强，挑战更加轻松。\n（2）提升完成「记忆编码」挑战后获得的奖励。\n（3）激活活动玩法「边缘存储」。\n\n<Title: 边缘存储>\n1、激活共鸣「诊断：人格分裂」后，每小时自动获得「记忆拼图α」×  60，最多储存 25 小时。\n2、激活共鸣「认知同调」后，每小时自动获得「记忆拼图β」× 30，最多储存 25 小时。\n\n<Title:特遣纪录>\n1、活动期间，「特遣纪录：宁静的裂殖」可免费解锁。\n2、活动结束后，「特遣纪录：宁静的裂殖」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「特遣纪录：宁静的裂殖」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「特遣纪录：宁静的裂殖」后都可以获得「钥令：全部的她」。\n\n<Title:复刻补偿>\n1、此前已经解锁「特遣纪录：宁静的裂殖」的守密人，在本次复刻活动期间重新解锁时将会获得「记忆拼图α」×700的补偿。\n2、此前已经获得活动限定头像「以银钥之名：「24」」的守密人，重复获得时将自动转换为「无形者的请柬」×1。\n3、此前已经获得激活共鸣材料「分裂之心」的守密人，每获得 1 个多余的「分裂之心」将自动转换为「蔷薇金券」×5000。\n"
  },
