  },
  Activity_126275_ActivityTips = {
    Text = "<Title:活动简介>\n活动期间，守密人可通过限时玩法「木偶的舞台」和「成就奖励」收集活动货币「丝绒座票根」，「丝绒座票根」可在「剧院礼品店」中换取奖励，包括活动限定SR命轮「宿命纺轮」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n\n<Title:木偶的舞台>\n1、「木偶的舞台」包含 5 个无需探索直接战斗的素材关卡，每 2 天开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得培养素材和活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「木偶的舞台」关卡任务报酬中的「丝绒座票根」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「阿拉克涅」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「永世编织之网」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「宿命纺轮」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title: 剧院礼品店>\n1、每次「礼品兑换」将消耗 750「丝绒座票根」，随机获得「剧院礼品店」中的五个物品奖励。\n2、「剧院礼品店」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 5 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 6 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动时间>\n1、4 月 20 日 9:00 - 5 月 18 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、5 月 18 日 9:00 - 5 月 25 日 9:00（GMT+8），仅保留「剧院礼品店」和「成就奖励」，其他内容均已结束不可参与。\n3、5 月 25 日 9:00（GMT+8）后，剩余未兑换的「丝绒座票根」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
  Activity_126275_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_126365_ActivityName = {
    Text = "命缕纪行"
  },
  Activity_126365_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「命缕纪行」中领取奖励。\n2、「命缕纪行」永久开放。\n3、解锁「高级纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_126366_ActivityName = {
    Text = "历程追思献礼·星辰篇Ⅴ"
  },
  Activity_126366_ActivityPlot = {
    Text = "一段记忆尘封归档，一段历程载入过往。追思之时，勿忘献上崇敬之礼。"
  },
  Activity_126492_ActivityName = {
    Text = "古国杂俎"
  },
  Activity_126492_ActivityTips = {
    Text = "<Title: 古国杂俎>\n·本次限时纪行包含 8 个礼包，其中首个礼包可直接免费领取，第 2-8 个礼包需要购买「古国杂俎」后方可领取。\n·购买「古国杂俎」后可立即领取第 2 个礼包奖励；后续礼包需要分别等待一定时间后才可领取。\n·在 1 月 26 日 9：00 前购买「古国杂俎」还可额外获得奖励：专属头像「扇中真形」、「无形者的请柬」×10！在 1 月 26 日 9：00 后购买将不再获得限时专属奖励。 \n· 购买后，本次限时纪行的持续时间将会变为永久，当领取完所有的礼包后次日活动关闭。\n·「古国杂俎」购买有时间限制，逾期将无法再购买。请守密人在 2 月 23 日 9：00 前酌情购买。"
  },
  Activity_126492_BannerText = {
    Text = "特别纪行活动限时开启！"
  },
  Activity_127173_ActivityName = {Text = "绘者"},
  Activity_127173_ActivityTips = {
    Text = "<Title:活动规则>\n·「绘者」活动开启期间，守密人可使用包含皮克曼的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_129488_ActivityName = {
    Text = "疾驰的欢愉专列"
  },
  Activity_129488_ActivityPlot = {
    Text = "列车上，烦躁的咆哮声不断从雅室传出。\n「萨尔瓦多，第三节车厢需要支援！」\n「旺达，把你控制的敌人派去车尾，它们追上来了！」\n「莱克！别搭讪了！快来把我窗外的家伙赶走！」\n正在豪华包厢焦头烂额的你，完全没留意到，一个小小的身影，已经偷偷潜入了你的口袋。\n「嘻嘻，果然要这样才有趣。」\n「拍下了不错的影像嘛~那么接下来——该帮手小「N」出场了~ 」"
  },
  Activity_129488_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过「专列轨迹」来获取丰富的限时奖励，活动结束后「专列轨迹」中的奖励将无法再领取，请各位守密人及时领取限时奖励。\n2、活动期间，参与「列车启程」会获得等级补偿，具体规则如下：\n  ·调查队伍中，等级不足 60 级的唤醒体在本次挑战中将会补偿至 60 级。\n  ·调查队伍中，技能等级不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n  ·调查队伍中，「疯狂预兆」不足 6 级的唤醒体在本次挑战中将会补偿至 6 级。\n  ·调查队伍中，「灵塑适性」不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n  ·若守密人等级不足60级，在本次挑战中将会补偿至60级。\n\n<Title:特遣纪录>\n1、活动期间「特遣纪录：开往祈岁节的列车」将免费开放。\n2、活动结束后，「特遣纪录：开往祈岁节的列车」的调查进度会保留，如果活动期间未解锁「特遣纪录：开往祈岁节的列车」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「特遣纪录：开往祈岁节的列车」后都可以获得「钥令：岁末花火」。\n\n<Title:疾驰的欢愉专列>\n1、「疾驰的欢愉专列」是采用「星辰篇」规则的连续挑战模式。守密人将在多变的随机遭遇中连续挑战多个调查行动中出现过的最终首领！\n2、玩法中造物持有上限最高可提升至 36 个。\n3、挑战过程中可同时拥有并强化 3 种调查行动中的强大「共鸣」效果。\n4、每使用 1 次应急灵知体，会减少 20% 本次挑战获取的「贵宾积分」。\n5、支持中途退出并保留进度，但队伍状态不会随外部养成变化同步更新。进度至多保留至上一次挑战的 7 天后，若保留期间没有继续挑战则视为放弃挑战，进度不再保留。\n\n<Title:贵宾名录>\n1、活动期间，「贵宾名录」中的记录将会保留，活动结束后会跟随学园活动的周期重置记录。\n2、「贵宾名录」会记录挑战表现优异的守密人，每期学园活动期间挑战 1 次，并且成功获得「贵宾积分」的守密人即可进入「贵宾名录」。\n3、「贵宾名录」的排名会以单次挑战获得最多的「贵宾积分」和所用最少的「回合数」为依据，可重复挑战以提高排名。\n\n<Title:活动时间>\n1、2 月 9 日 9:00 - 3 月 9 日 9:00（GMT+8），所有活动内容均可参与。\n2、3 月 9 日 9:00 （GMT+8）后，活动将会被收录至「记忆回廊」，「专列轨迹」中的奖励将无法再领取。"
  },
