  Activity_130925_ActivityName = {
    Text = "默斯克斯的呼唤"
  },
  Activity_130925_ActivityPlot = {
    Text = "大海的深处，漩涡正吞噬一切。\n默斯克斯下的恶魔张开巨口，平等地邀请所有靠近的生灵。\n它一日又一日地旋转，一遍又一遍地嘶吼，呼唤那终将到来的注定之人。\n来吧，来吧，「水草」会缠绕你，「礁石」会陪伴你，在漆黑的海底中，你注定与灾祸共舞。\n而灾祸， 也将回应你最后的请求。\n欢迎回家，无法选择的注定之人。"
  },
  Activity_130925_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「莫丝的宝库」"
  },
  Activity_130925_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「莫丝与海」和「成就奖励」收集活动货币「海螺一号」、「海螺二号」、「海螺三号」，「海螺一号」、「海螺二号」、「海螺三号」可在「莫丝的宝库」中购买商品，包括活动限定SR命轮「被囚禁的疯狂」、流明之芯、无垢之芯等。\n2、活动期间，「意识潜游：沉溺」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：莫丝」！\n\n<Title:活动时间>\n1、3 月 9 日 9:00 - 4 月 6 日 9:00（GMT+8），所有活动玩法均可参与。\n2、4 月 6 日 9:00 - 4 月 13 日 9:00（GMT+8），仅可参与「莫丝的宝库」和成就奖励。\n\n<Title:莫丝与海>\n1、「莫丝与海」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 莫丝的宝库>\n1、「莫丝的宝库」共有三个商店，开启时间如下：\n·「宝箱一号」： 3 月 9 日 9 时开启。\n·「宝箱二号」： 3 月 10 日 9 时开启。\n·「宝箱三号」： 3 月 11 日 9 时开启。\n2、每次交换将消耗「海螺一号」/「海螺二号」/「海螺三号」× 750，随机获得「莫丝的宝库」中的五个物品奖励。\n3、每个「莫丝的宝库」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「莫丝的宝库」关卡任务报酬中的「海螺一号」、「海螺二号」、「海螺三号」获得额外的掉落加成，具体加成如下：\n·唤醒体「莫丝」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「渺远的伊甸园」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「被囚禁的疯狂」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:意识潜游>\n1、活动期间，「意识潜游：沉溺」可免费解锁。\n2、活动结束后，「意识潜游：沉溺」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「意识潜游：沉溺」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「意识潜游：沉溺」后都可以获得「钥令：溺亡的纯真」。"
  },
