  Activity_131849_ActivityTips = {
    Text = "<Title: 永恒的记忆>\n·本次限时纪行包含 8 个礼包，其中首个礼包可直接免费领取，第 2-8 个礼包需要购买「永恒的记忆」后方可领取。\n·购买「永恒的记忆」后可立即领取第 2 个礼包奖励；后续礼包需要分别等待一定时间后才可领取。\n·在 5 月 30 日 9：00 前购买「永恒的记忆」还可额外获得奖励：专属头像「愉快的猎食」、「无形者的请柬」×10！在 5 月 30 日 9：00 后购买将不再获得限时专属奖励。\n·「永恒的记忆」购买有时间限制，逾期将无法再购买。请守密人在 6 月 29 日 9：00 前酌情购买。"
