  Activity_133272_ActivityPlot = {
    Text = "一个伟大的时代或许终究会消亡，但那些伟大勇士的意志永远不会消亡。\n墓碑无法掩埋他们，锁链无法驯服他们。\n当新的征途出现，美味的烤肉在那征服之路的尽头招手，战士们发起冲锋，将那荣耀的战利品收入囊中。\n让我们为这不灭的英勇，为这神圣的帝国高歌！\n罗马！罗马！"
