  Activity_139116_ActivityName = {
    Text = "宛如梦幻的相逢"
  },
  Activity_139116_ActivityTips = {
    Text = "<Title:活动规则>\n·守密人完成指定的纪行任务后，可以在「宛如梦幻的相逢」中领取奖励。\n·解锁「高级纪行」后，完成任务后可额外领取奖励。\n·本次「高级纪行」购买有时间限制，逾期将无法再购买。请守密人在 6 月 29 日9：00（GMT+8）前酌情购买。\n·请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_139116_BannerText = {
    Text = "免费领取全新限定唤醒体!"
  },
  Activity_139117_ActivityName = {
    Text = "虚梦礼赠"
  },
  Activity_139117_ActivityTips = {
    Text = "<Title:简介>\n·活动期间，守密人完成指定目标后可以在「虚梦礼赠」中领取对应奖励。"
  },
  Activity_139117_BannerText = {
    Text = "免费领取群星余梦!"
  },
  Activity_139591_ActivityName = {
    Text = "猫的「报恩」"
  },
  Activity_139591_ActivityPlot = {
    Text = "「紧急通知，请全校师生立刻结束现有工作，协助抓捕出逃实验体。」\n「重复一遍，请全校师生立刻结束现有工作，协助抓捕出逃……该死！这些猫进来了！」\n当你听到广播中慌乱的声音时，整个校园已经被黑色绒毛淹没，大家正手忙脚乱地抓捕这些逃出实验室的小坏蛋。\n似乎是为了报祈岁节的仇，这些黑猫正缓慢而有序地向你的宿舍汇聚。\n不过嘛……考虑到他们携带的大量金券和银芯，你很难说它们是来报仇的，还是来「报恩」的。\n注意，不要过度捕捞哦。"
  },
  Activity_139591_ActivityStageEndContent = {
    Text = "活动已结束"
  },
  Activity_139591_ActivityTips = {
    Text = "<Title: 猫的「报恩」>\n·猫的「报恩」包含 7 个不可重现、直接挑战的关卡，活动每天开放 1 关。\n·每次挑战战胜对应的「维度黑猫」后，即可累积任务进度，在「黑猫抓捕记录」中领取相应奖励。\n·每种「维度黑猫」均有大量分身，活动期间可以不限次数的参与挑战，挑战支持自动战斗。\n·每个关卡会提供不同的造物，将会为你提供强大的加成。\n·所有关卡必须选择助战，整个活动中，每个互相关注的守密人只能为你提供一次助战。\n\n<Title: 等级补偿>\n·在猫的「报恩」中有等级补偿机制，以便各位守密人能够并肩作战！\n等级补偿规则如下：\n  ·调查队伍中，等级不足 60 级的唤醒体在本次挑战中将会补偿至 60 级。\n  ·调查队伍中，技能等级不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n  ·调查队伍中，「疯狂预兆」不足 6 级的唤醒体在本次挑战中将会补偿至 6 级。\n  ·调查队伍中，「灵塑适性」不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n  ·若守密人等级不足60级，在本次挑战中将会补偿至60级。\n\n<Title:黑猫抓捕记录>\n·活动期间，守密人在战胜对应的「维度黑猫」后，可累积对应任务进度，在「黑猫抓捕记录」中领取相应奖励，分为「个人抓捕记录」与「校园抓捕记录」。「个人抓捕记录」为守密人的个人任务。「校园抓捕记录」为校园全体守密人的任务。\n\n<Title:抓捕排行>\n·活动期间，守密人可以在「抓捕排行」中查看「抓捕次数榜」与「协助次数榜」。\n\n<Title:活动时间>\n· 6 月 15 日 9:00 （GMT+8）前，守密人可进入活动页参与活动。在此时间后不再接受新的守密人加入挑战。若活动尚未结束，已参与的守密人可继续进行挑战。\n·若在 6 月 15 日 9:00 （GMT+8）前达成「抓捕总数」，则活动将在 6 月 29 日 9:00 （GMT+8）结束。若未在 6 月 15 日 9:00 （GMT+8）前达成「抓捕总数」，则活动在达成「抓捕总数」的 14 天后结束。"
  },
