  },
  Activity_141467_ActivityName = {
    Text = "镜像囚徒·复刻"
  },
  Activity_141467_ActivityPlot = {
    Text = "飞鸟啊飞鸟，你的脚上为何有断裂的镣铐？\n飞鸟啊飞鸟，你为何在高空之上孤独地鸣叫？\n挣脱荆棘、逃离囚笼，你展翅飞过了漫漫黄沙，只是你悲伤的鸣叫不曾停止。究竟何人，才是你寻找的忠诚旅伴？究竟何处，才是你寻找的真正家乡？"
  },
  Activity_141467_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「求知的愿望」"
  },
  Activity_141467_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「飞跃青空」、「梦境巡梭」和「成就奖励」收集活动货币「常识之书」、「数理之书」、「文学之书」，「常识之书」、「数理之书」、「文学之书」可在「求知的愿望」中购买商品，包括活动限定SR命轮「孤羽」、流明之芯、无垢之芯等。\n2、活动期间，「异梦视界：天边之外·上」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：卡斯托尔」！\n\n<Title:活动时间>\n1、10 月 5 日 9:00 - 11 月 2 日 9:00（GMT+8），所有活动玩法均可参与。\n2、11 月 2 日 9:00 - 11 月 9 日 9:00（GMT+8），仅可参与「求知的愿望」和成就奖励。\n\n<Title:飞跃青空>\n1、「飞跃青空」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 求知的愿望>\n「求知的愿望」共有三个商店，开启时间如下：\n·「通识选修课」： 10 月 5 日 9 时开启。\n·「科学选修课」： 10 月 6 日 9 时开启。\n·「文学选修课」： 10 月 7 日 9 时开启。\n在商店内可以选择商品直接进行购买。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「飞跃青空」关卡任务报酬中的「常识之书」、「数理之书」、「文学之书」获得额外的掉落加成，具体加成如下：\n·唤醒体「卡斯托尔」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「不可承受的自由」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「孤羽」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title: 梦境巡梭>\n1、每小时自动获得 60「常识之书」，最多储存 25 小时。\n\n<Title:异梦视界>\n1、活动期间，「异梦视界：天边之外·上」可免费解锁。\n2、活动结束后，「异梦视界：天边之外·上」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「异梦视界：天边之外·上」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：天边之外·上」后都可以获得「钥令：错位命运」。"
  },
  Activity_141467_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_141509_ActivityName = {
    Text = "秘境游记"
  },
  Activity_141509_ActivityTips = {
    Text = "<Title:活动规则>\n1、守密人完成指定的纪行任务后，可以在「秘境游记」中领取奖励。\n2、「秘境游记」将会在 7 月 27 日 09:00 结束。\n3、解锁「高级纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_141509_BannerText = {
    Text = "特别纪行活动限时开启！"
  },
  Activity_141533_ActivityName = {
    Text = "永远的厄波扬斯"
  },
  Activity_141533_ActivityPlot = {
    Text = "让我们纵声大笑，让我们彻夜欢庆。\n让我们的钩爪刺穿敌人的咽喉，让庸常的时光在深渊里生锈。\n我们再也不会被衰老、平凡和孤独抓住。\n这里是厄波扬斯，我们永远快乐，我们永远相聚。\n我们永不分离。"
  },
  Activity_141533_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「无边猎场」"
  },
  Activity_141533_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「高屋巡猎」和「成就奖励」收集活动货币「新鲜的「猎物」」「硕大的「猎物」」「古老的「猎物」」，并在「无边猎场」中兑换商品，包括活动限定SR命轮「指向歧路的罗盘」、流明之芯、无垢之芯等。\n2、活动期间，「意识潜游：永远的厄波扬斯」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：庞托斯」！\n\n<Title:活动时间>\n1、6 月 29 日 9:00 - 7 月 27 日 9:00（GMT+8），所有活动玩法均可参与。\n2、7 月 27 日 9:00 - 8 月 3 日 9:00（GMT+8），仅可参与「无边猎场」和成就奖励。\n\n<Title:高屋巡猎>\n1、「高屋巡猎」包含 7 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 无边猎场>\n「无边猎场」共有三个商店，开启时间如下：\n·「铁弓箭」： 6 月 29 日 9 时开启。\n·「热武器」： 6 月 30 日 9 时开启。\n·「魔法」： 7 月 1 日 9 时开启。\n在商店内可以选择商品直接进行购买。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「高屋巡猎」关卡任务报酬中三种活动货币的掉落获得额外加成：\n·唤醒体「庞托斯」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「活囚笼」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「指向歧路的罗盘」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:意识潜游>\n1、活动期间，「意识潜游：永远的厄波扬斯」可免费解锁。\n2、活动结束后，调查进度将保留，活动期间未完成的调查事件在活动后继续完成同样可获得对应奖励。如活动期间未解锁，活动结束后仍可消耗「现实起点」× 3 解锁。\n3、无论是否在活动期间，通关「意识潜游：永远的厄波扬斯」均可获得「钥令：空心人」。"
  },
