  },
  Activity_145458_ActivityTips = {
    Text = "<Title:活动简介>\n活动期间，守密人可通过限时玩法「贪戮角逐」和「成就奖励」收集活动货币「血色祭品」，「血色祭品」可在「斗兽场祭祀台」中换取奖励，包括活动限定SR命轮「不灭的饥骨」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n\n<Title:贪戮角逐>\n1、「贪戮角逐」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「血色祭品」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「贪戮角逐」关卡任务报酬中的「血色祭品」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「蚀灭·萝坦」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「天之陨」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「不灭的饥骨」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title:意识潜游>\n1、活动期间，「意识潜游：直至鲸天陨落」可免费解锁。\n2、活动结束后，「意识潜游：直至鲸天陨落」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「意识潜游：直至鲸天陨落」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「意识潜游：直至鲸天陨落」后都可以获得「钥令：噬鲸的风暴」。\n\n<Title:活动时间>\n1、7 月 27 日 9:00 - 8 月 24 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、8 月 24 日 9:00 - 8 月 31 日 9:00（GMT+8），仅保留「斗兽场祭祀台」和「成就奖励」，其他内容均已结束不可参与。\n3、8 月 31 日 9:00（GMT+8）后，剩余未兑换的「血色祭品」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
  Activity_145458_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_145459_ActivityName = {
    Text = "支线关卡免费解锁"
  },
  Activity_145465_ActivityName = {
    Text = "如果一切如常·复刻"
  },
  Activity_145465_ActivityPlot = {
    Text = "你曾幻想过，如果灾难不曾来临，所有人的生活究竟会是什么样子。\n你拯救世界的力量没有了用武之地， 每天都要为平凡的校园生活和赚取可怜的学分奔波。操场上再也没有了训练作战的身影，取而代之的是一排排社团活动的帆布棚子，与招揽、嬉闹的叫嚷声；待放学的钟声敲响，饥饿的学生们便立刻挤满了食堂……\n敲开你牵挂着的人们的房门，你会看到怎样的笑脸？"
  },
  Activity_145465_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「学生会办公楼」"
  },
  Activity_145465_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「日光下新事」收集活动货币「海滨特产贝壳」，「海滨特产贝壳」可在「学生会办公楼」中购买商品，包括流明之芯、无垢之芯、贤石碎屑等。\n2、活动期间，「异梦视界：再见，永无乡」限时免费解锁！\n\n<Title:活动时间>\n1、8 月 3 日 9:00 - 8 月 17 日 9:00（GMT+8），所有活动玩法均可参与。\n2、8 月 17 日 9:00 - 8 月 24 日 9:00（GMT+8），仅可参与「学生会办公楼」和成就奖励。\n\n<Title:日光下新事>\n1、「日光下新事」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 学生会办公楼>\n「学生会办公楼」共有一个商店， 8 月 3 日 9 时开启。\n在商店内可以选择商品直接进行购买。\n\n<Title:异梦视界>\n1、活动期间，「异梦视界：再见，永无乡」可免费解锁。\n2、活动结束后，「异梦视界：再见，永无乡」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「异梦视界：再见，永无乡」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：再见，永无乡」后都可以获得「钥令：美梦一刹」。"
  },
  Activity_145465_BannerText = {
    Text = "玩法活动限时开启！"
