  Activity_145466_ActivityName = {
    Text = "支线关卡免费解锁"
  },
  Activity_145717_ActivityName = {
    Text = "新月与深雪"
  },
  Activity_145717_ActivityPlot = {
    Text = "七重礼拜，三重宣誓，只要怀着对那纯白仙女虔诚的信仰攀上天与雪的交际，她就会实现你所有、所有的愿望。\n每一个人都有不同的目的，每一个目的下都有不同的谎言。\n将祂们挖掘，将祂们呈现——在屈从于无瑕的表象之前。\n不要和她一同没入这片深雪。"
  },
  Activity_145717_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「仙女典仪」"
  },
  Activity_145717_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「乌摩钵蒂的宝物」和「成就奖励」收集活动货币「红苹果」「金苹果」「糖苹果」，并在「仙女典仪」中兑换商品，包括活动限定SR命轮「恬美真相」、流明之芯、无垢之芯等。\n2、活动期间完成活动成就还能获得活动限定头像「以银钥之名：卡拉布」！\n\n<Title:活动时间>\n1、8 月 24 日 9:00 - 9 月 21 日 9:00（GMT+8），所有活动玩法均可参与。\n2、9 月 21 日 9:00 - 9 月 28 日 9:00（GMT+8），仅可参与「仙女典仪」和成就奖励。\n\n<Title:乌摩钵蒂的宝物>\n1、「乌摩钵蒂的宝物」包含 7 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 仙女典仪>\n1、「仙女典仪」共有三个商店，开启时间如下：\n·「浅雪赐福」： 8 月 24 日 9 时开启。\n·「寒霜赐福」： 8 月 25 日 9 时开启。\n·「纯白赐福」： 8 月 26 日 9 时开启。\n2、每次「沐受赐福」将消耗「红苹果」/「金苹果」/「糖苹果」× 750，随机获得「仙女典仪」中的五个物品奖励。\n3、每个「仙女典仪」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「乌摩钵蒂的宝物」关卡任务报酬中三种活动货币的掉落获得额外加成：\n·唤醒体「卡拉布」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「蜜果的谎言」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「恬美真相」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、多项「活动加成」可叠加计算。 \n3、注意，癫狂难度首通挑战奖励不会受到「活动加成」影响。"
  },
