  Activity_15793_ActivityName = {
    Text = "雨镇幽影"
  },
  Activity_15793_ActivityPlot = {
    Text = "每个下着雨的夜晚，都伴随着失意与寂寥。\n有人失去爱情，有人失去尊严。\n还有人失去自己的头颅。"
