  Activity_15793_ActivityTips = {
    Text = "<Title:参与条件>\n·完成「调查行动」2-9·普通后可参与。\n<Title:调查事件>\n·活动期间，每天会推出「雨镇幽影」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「雨镇幽影」的调查进度会保留，守密人可以在特遣纪录中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「雨镇幽影」普通模式和完成「雨镇幽影」的调查事件后，可以获得无垢之芯、贤者之石和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
