    Text = "活动规则：\n1、「强效特训」活动期间，守密人通关「波纳佩之墟」后，部分素材奖励将会翻倍，每天可享受3次。\n2、当日未使用完毕的双倍奖励次数将在次日9点（GMT+8）清空，请守密人记得及时使用喔~"
  },
