  },
  Activity_20690_ActivityTips = {
    Text = "活动规则：\n1、「升格演绎」活动期间，守密人通关「浑浊残像」后，部分素材奖励将会翻倍，每天可享受3次。\n2、当日未使用完毕的双倍奖励次数将在次日9点（GMT+8）清空，请守密人记得及时使用喔~"
  },
  Activity_20691_ActivityName = {
    Text = "猎颅魔女"
  },
  Activity_20691_ActivityTips = {
    Text = "<Title:活动规则>\n·「猎颅魔女」活动开启期间，守密人可使用包含达芙黛尔的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_21502_ActivityName = {
    Text = "海之使徒"
  },
  Activity_21502_ActivityTips = {
    Text = "<Title:活动规则>\n·「海之使徒」活动开启期间，守密人可使用包含弥利亚姆的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_21781_ActivityName = {
    Text = "研习自选"
  },
  Activity_21781_ActivityPlot = {
    Text = "完成任务，可任选「界域研习」中的特定唤醒体或「轮转之相」中的特定命轮！"
  },
  Activity_21781_ActivityTips = {
    Text = "活动规则：\n1、累计唤醒 50 次、累计登录3天、累计登录 7 天，可获得「原质乐园」奖励。「原质乐园」可在「物资：消耗品」中使用，使用后可任选1名「界域研习」中的特定唤醒体唤醒。\n2、累计唤醒 300 次、累计唤醒 1000 次、累计登录 30 天，可获得「轮转之书」奖励。「轮转之书」可在「物资：消耗品」中使用，使用后可任选1个「轮转之相」中的特定命轮获得。"
  },
  Activity_22367_ActivityName = {
    Text = "灵知迸发"
  },
  Activity_22367_ActivityTips = {
    Text = "活动规则：\n1、「灵知迸发」活动期间，守密人在「制剂淬炼」调查或重现，将获得额外50%的奖励（守密人经验除外），每天不限次。"
  },
  Activity_23671_ActivityName = {
    Text = "深潜对弈"
  },
  Activity_23671_ActivityPlot = {
    Text = "活动期间，守密人通过「幻梦深潜」和「相位对弈」获取的守密人经验将会翻倍，每日上限提升至480点。"
  },
  Activity_23671_ActivityTips = {
    Text = "活动规则：\n1、「深潜对弈」活动期间，守密人通过「幻梦深潜」和「相位对弈」获取的守密人经验将会翻倍，每日上限提升至480点。若同时解锁了核心课题，通过该途径获得的守密人经验将会翻倍再翻倍，每日上限维持480点不变。\n2、当日未使用完毕的双倍守密人经验将在次日9点（GMT+8）清空，守密人记得及时清空哦~"
  },
  Activity_23693_ActivityName = {
    Text = "苍白后裔"
  },
  Activity_23693_ActivityPlot = {
    Text = "相传在伦蒂尼恩的地下，有一扇唯一的门。\n它通向苍白之主的所在……"
  },
  Activity_23693_ActivityTips = {
    Text = "<Title:参与条件>\n·完成意识潜游「骑士的愿望」普通模式后可参与。 \n<Title:调查事件>\n·活动期间，每天会推出「苍白后裔」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「苍白后裔」的调查进度会保留，守密人可以在意识潜游中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「苍白后裔」普通模式和完成「苍白后裔」的调查事件后，可以获得漆黑锁扣和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
  Activity_23693_UnlockConditionExplanation = {
    Text = "完成意识潜游「骑士的愿望」后解锁"
  },
  Activity_23723_ActivityName = {
    Text = "风暴将至"
  },
  Activity_23723_ActivityTips = {
    Text = "活动规则：\n1、活动期间，调查行动第五章临时关闭，钥令「永世执念」暂时由通关调查行动第四章获得。\n2、活动结束后，调查行动第五章再度开放，钥令「永世执念」仍然需要通关调查行动第五章。\n3、另外，此前已达成的第五章成就奖励、关卡成就奖励、探索奖励、通关奖励都会保留，再度开放时（当前计划为  12 月 27 日），相关已完成进度会尽可能平移保留，无需重复完成。"
  },
  Activity_23870_ActivityName = {
    Text = "相位推演"
  },
  Activity_23870_ActivityTips = {
    Text = "活动规则：\n1、活动期间，完成活动任务即可获得奖励。\n2、活动结束后，未领取的活动奖励将无法再领取，请守密人记得及时领取~"
  },
