  Activity_24194_ActivityName = {Text = "红夫人"},
  Activity_24194_ActivityTips = {
    Text = "<Title:活动规则>\n·「红夫人」活动开启期间，守密人可使用包含索蕾尔的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_24195_ActivityName = {
    Text = "淤泥之花"
  },
  Activity_24195_ActivityTips = {
    Text = "<Title:活动规则>\n·「淤泥之花」活动开启期间，守密人可使用包含莉莉的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_24992_ActivityName = {
    Text = "学园礼赠"
  },
  Activity_24992_ActivityTips = {
    Text = "活动规则：\n1、守密人每天登录后可以在「学园礼赠」中领取当日签到奖励。\n2、奖励将根据守密人累计登录依次解锁，当日签到奖励将在9点（GMT+8）刷新。"
  },
  Activity_25011_ActivityName = {
    Text = "一步之遥"
  },
  Activity_25011_ActivityPlot = {
    Text = "你向前一步，跨入了另一个时空。"
  },
  Activity_25011_ActivityTips = {
    Text = "<Title:参与条件>\n·完成意识潜游「骑士的愿望」普通模式后可参与。 \n<Title:调查事件>\n·活动期间，每天会推出「一步之遥」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「一步之遥」的调查进度会保留，守密人可以在意识潜游中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「一步之遥」普通模式和完成「一步之遥」的调查事件后，可以获得幸运糖果和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
  Activity_25011_UnlockConditionExplanation = {
    Text = "完成意识潜游「骑士的愿望」后解锁"
  },
  Activity_25012_ActivityName = {
    Text = "蔷薇礼赞"
  },
  Activity_25012_ActivityPlot = {
    Text = "女士们，先生们。\n温和的良夜已经拉开帷幕，准备好手边的佳酿吧。\n这是一个漫长的故事，且听我们慢慢道来……"
  },
  Activity_25012_ActivityTips = {
    Text = "<Title:参与条件>\n·完成「调查行动」2-9·普通后可参与。\n<Title:调查事件>\n·活动期间，每天会推出「蔷薇礼赞」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「蔷薇礼赞」的调查进度会保留，守密人可以在特遣纪录中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「蔷薇礼赞」普通模式和完成「蔷薇礼赞」的调查事件后，可以获得无垢之芯、贤者之石和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
  Activity_25012_UnlockConditionExplanation = {
    Text = "完成 「调查行动」2-9·普通 后解锁"
  },
  Activity_34754_ActivityName = {
    Text = "故事的魔法"
  },
  Activity_34754_ActivityTips = {
    Text = "<Title:参与条件>\n·完成「调查行动」2-9·普通后可参与。\n<Title:调查事件>\n·活动期间，每天会推出「故事的魔法」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「故事的魔法」的调查进度会保留，守密人可以在特遣纪录中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「故事的魔法」普通模式和完成「故事的魔法」的调查事件后，可以获得无垢之芯、贤者之石和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
  Activity_34755_ActivityName = {
    Text = "故事的魔法"
  },
  Activity_34755_ActivityTips = {
    Text = "<Title:活动简介>\n·活动期间「剧本迷思」玩法限时开启，且「特遣纪录：故事的魔法」免费解锁开启！\n\n<Title:剧本迷思>\n·「剧本迷思」共包含 9 个难度的关卡，推荐等级范围为 30~70，通关较低的难度的关卡后解锁更高难度的关卡。\n·每次挑战需要消耗灵啡肽×60，每次通关后都可以获得活动货币「飘零的灵感」。关卡难度越高，获取的「飘零的灵感」就越多！\n·「飘零的灵感」可以在「魔法剧本商店」兑换大量的唤醒体培养素材，还可以兑换活动限定 SR 命轮「35mm的魔法」，该命轮在未来可能会再次推出或加入常驻唤醒。\n·每次挑战时，除首领之外的敌人、事件、地图都可能发生一定的变化，关卡内可能出现的造物也更多！\n·在「剧本迷思」中可以使用校友会助战。\n\n<Title:共鸣与成就>\n·消耗「演绎之心」，激活「共鸣：导演密码」，可以让守密人在「剧本迷思」中变得更强，挑战更加轻松。\n·守密人可以通过达成活动成就获取「演绎之心」，除此之外通过活动成就还可以获得活动限定头像「以银钥之名：莉莉」！\n\n<Title:特遣纪录>\n·活动期间，每天会推出「故事的魔法」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「故事的魔法」的调查进度会保留，守密人可以在特遣纪录中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。\n·活动期间会推出限时成就奖励，守密人通关「故事的魔法」普通模式和完成「故事的魔法」的调查事件后，可以在活动成就中领取银芯奖励！成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n"
  },
