  Activity_35844_ActivityName = {
    Text = "深海淑女"
  },
  Activity_35844_ActivityTips = {
    Text = "<Title:活动规则>\n·「深海淑女」活动开启期间，守密人可使用包含墨菲的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_35983_ActivityName = {
    Text = "学园礼赠"
  },
  Activity_35983_ActivityTips = {
    Text = "活动规则：\n1、守密人每天登录后可以在「学园礼赠」中领取当日签到奖励。\n2、奖励将根据守密人累计登录依次解锁，当日签到奖励将在9点（GMT+8）刷新。"
  },
  Activity_36841_ActivityName = {
    Text = "诸事如常"
  },
  Activity_36841_ActivityPlot = {
    Text = "这是奥瑞塔简单而开心的一天，这是她的每一天。"
  },
  Activity_36841_ActivityTips = {
    Text = "<Title:参与条件>\n·完成意识潜游「骑士的愿望」普通模式后可参与。 \n<Title:调查事件>\n·活动期间，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「诸事如常」的调查进度会保留，守密人可以在意识潜游中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「诸事如常」普通模式和完成「诸事如常」的调查事件后，可以获得漆黑锁扣和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
  Activity_36841_UnlockConditionExplanation = {
    Text = "完成意识潜游「骑士的愿望」后解锁"
  },
  Activity_36885_ActivityName = {
    Text = "燃烧的群宴"
  },
  Activity_36886_ActivityName = {
    Text = "荆棘女王"
  },
  Activity_36886_ActivityTips = {
    Text = "<Title:活动规则>\n·「荆棘女王」活动开启期间，守密人可使用包含旺达的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_38716_ActivityName = {
    Text = "调查重启"
  },
  Activity_38716_ActivityTips = {
    Text = "<Title:活动简介>\n·守密人可以在「返校奖励」中直接领取「重启补给」奖励。\n·完成指定的训练任务，可以在「调查重启」活动中领取奖励。\n·完成全部训练任务，还可领取额外奖励。"
  },
  Activity_38717_ActivityName = {
    Text = "返校报到"
  },
  Activity_38717_ActivityTips = {
    Text = "<Title:活动简介>\n·守密人每天登录后可以在「返校报道」中领取当日签到奖励。\n·奖励将根据守密人累计登录依次解锁，当日签到奖励将在9点（GMT+8）刷新。"
  },
  Activity_38805_ActivityName = {
    Text = "燃烧的群宴"
  },
  Activity_38805_ActivityPlot = {
    Text = "伊萨拉乌，湖中之城，据说是旺达故乡的所在。\n这次你将穿过梦境的大门，抵达那遍布钟舌的古老塔群……"
  },
  Activity_38805_ActivityTips = {
    Text = "<Title:活动简介>\n·活动期间「燃烧的群宴」玩法限时开启，且「意识潜游：燃烧的群宴」限时免费解锁！\n\n<Title:湖中之城>\n·「湖中之城」有 7 个关卡，每 2 天开放 1 个！每个关卡的敌人与事件都可能发生随机变化。\n·请注意，每个关卡奖励的素材种类、数量、混合比例都可能发生变化，越早开放的关卡种类更单纯，越晚开放的关卡种类更丰富但总量会更多，请按自己的需要选择攻略方法吧！\n·每个关卡共包含 7 个难度的关卡，推荐等级范围为 15~65，所有难度均默认解锁。\n·每次挑战需要消耗灵啡肽×120，难度越高，获取的奖励就越多，请选择适合自己的难度进行挑战。\n·关卡奖励的素材可以在「旺达的奇珍宝匣」商店兑换大量的唤醒体培养素材，还有活动限定头像「以银钥之名：旺达」。\n·可以使用校友会助战和「共鸣：代行密令」来帮助你更轻松地过关。。\n\n<Title:共鸣与成就>\n·消耗「享乐之心」，激活「共鸣：代行密令」，可以让守密人在「湖中之城」中变得更强，挑战更加轻松；也可以让守密人在通关时获得额外的活动货币。\n·守密人可以通过达成活动成就获取「享乐之心」，也可在「旺达的奇珍宝匣」商店兑换。\n\n<Title:意识潜游>\n·活动期间，「燃烧的群宴」可免费解锁。每天会推出「燃烧的群宴」中一个新的调查事件，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「燃烧的群宴」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「燃烧的群宴」，活动结束后仍然可以消耗「现实起点」×3解锁。\n·活动期间会推出限时成就奖励，守密人完成「燃烧的群宴」的调查事件后，可以在活动成就中领取银芯奖励！成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n"
  },
  Activity_41378_ActivityName = {
    Text = "迎灾特训"
  },
  Activity_41378_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的任务后，可以在「迎灾特训」中领取奖励。\n2、「迎灾特训」永久开放。\n3、解锁「高级纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_43569_ActivityName = {
    Text = "远洋纪行"
  },
  Activity_43569_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「远洋纪行」中领取奖励。\n2、「远洋纪行」永久开放。\n3、解锁「高级纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_43570_ActivityName = {
    Text = "雪镇纪行"
  },
  Activity_43570_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「雪镇纪行」中领取奖励。\n2、「雪镇纪行」永久开放。\n3、解锁「高级纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_43572_ActivityName = {
    Text = "炼金美学"
  },
  Activity_43572_ActivityTips = {
    Text = "活动规则：\n1、「炼金美学」活动期间，守密人在「金券搜查」调查或重现，将获得额外100%的奖励（守密人经验除外），每天限 6 次。"
  },
  Activity_43573_ActivityName = {
    Text = "炼金美学"
  },
  Activity_43573_ActivityTips = {
    Text = "活动规则：\n1、「炼金美学」活动期间，守密人在「金券搜查」调查或重现，将获得额外50%的蔷薇金券奖励。"
  },
  Activity_43574_ActivityName = {
    Text = "炼金美学"
  },
  Activity_43574_ActivityTips = {
    Text = "活动规则：\n1、「炼金美学」活动期间，守密人在「金券搜查」调查或重现，将获得额外50%的蔷薇金券奖励。"
  },
  Activity_44273_ActivityName = {
    Text = "灵魂的牧人"
  },
  Activity_44273_ActivityPlot = {
    Text = "他为你们受过苦，担了你们的劫难。\n因他付出的血肉，你们得了医治；\n因他付出的生命，你们得了宽恕。"
  },
  Activity_44273_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「圣堂之路」、「市民的善意」和「成就奖励」收集活动货币「义卖券」，「义卖券」可在「圣堂义卖现场」中换取随机商品，包括活动限定SR命轮「镜中人」、无垢之芯、流明之芯等。\n2、通关「特遣纪录：血的颜色」可获得全新钥令「神迹降临」。活动期间，「特遣纪录：血的颜色」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：萨尔瓦多」！\n\n<Title:圣堂之路>\n1、「圣堂之路」包含 5 个关卡，守密人通过完成「特遣纪录：血的颜色」的第2/4/6/7/9关可逐个解锁。\n2、每个关卡都有 7 个难度，推荐等级为 15~65，所有难度均默认解锁。每个关卡的敌人与事件都可能发生随机变化。\n3、可以使用校友会助战和「共鸣：灵魂的岔路」来帮助你更轻松地过关。\n4、每次挑战需要消耗 120 灵啡肽，难度越高，通关获取的「义卖券」就越多，此外守密人可以选择双倍挑战，消耗 240 灵啡肽，获得双倍的「义卖券」和守密人经验。\n\n<Title:辉光加成>\n1、在「灵魂辉光」的影响下，唤醒体「萨尔瓦多」、SSR命轮「神言石板」和SR命轮「镜中人」可以使「圣堂之路」关卡任务报酬中的「义卖券」获得额外的掉落加成，具体加成如下：\n（1）方式一：守密人拥有特定唤醒体或命轮（不要求上阵）\n·唤醒体「萨尔瓦多」：启灵0/1/2/3及以上，加成30%/40%/50%/60%。\n·SSR命轮「神言石板」：叠位0/1/2/3及以上，加成30%/40%/50%/60%。\n·SR命轮「镜中人」：叠位0/1/2/3及以上，加成15%/20%/25%/30%。\n（2）方式二：使用特定唤醒体或命轮助战\n·唤醒体「萨尔瓦多」：加成10% 。\n·SSR命轮「神言石板」：加成10% 。\n·SR命轮「镜中人」：加成5% 。\n2、对于同一唤醒体或命轮，两种方式的「辉光加成」取其中加成更高的方式生效，不叠加。\n3、不同唤醒体或命轮的「辉光加成」以叠加的方式结算，按照上述的规则，守密人最多可以获得 150% 的「辉光加成」！\n\n<Title:共鸣：灵魂的岔路>\n1、守密人可以通过完成活动成就获取「忏悔之心」。 \n2、消耗「忏悔之心」，激活「共鸣：灵魂的岔路」，可以获得以下加成：\n（1）让守密人在活动玩法「圣堂之路」和「特遣纪录：血的颜色」中变得更强，挑战更加轻松。\n（2）提升完成「圣堂之路」挑战后获得的同调率。\n（3）激活活动玩法「市民的善意」。\n\n<Title:市民的善意>\n1、激活共鸣「轻松的方式」后，每小时自动获得60「义卖券」，最多储存 25 小时。\n2、激活共鸣「赎罪，赎罪」后，每小时额外自动获得 1800 蔷薇金券。\n\n<Title: 圣堂义卖现场>\n1、守密人可以使用「义卖券」在「圣堂义卖现场」的商铺中随机换取商品，活动限定SR命轮「镜中人」、流明之芯和无垢之芯等商品在等着你~\n2、圣堂义卖现场共有三个商铺，开启时间如下：\n·商铺「格雷太太的小店」：初始开启。\n·商铺「大约翰的神奇义卖」：活动第4天开启。\n·商铺「史密斯特卖」：活动第7天开启。\n3、不同商铺的商品有所不同，守密人可根据自己的需要选择商品进行换取。\n4、每个商铺中都包含特殊商品和普通商品，每次换取将消耗600「义卖券」，随机获得商铺中的五个商品。\n5、当商铺中的所有特殊商品被换取后，守密人可以要求商铺补充货物，也可以选择继续换取。当商铺中所有的商品都被换取后，守密人需选择补充货物后才可继续换取。\n6、每个商铺的前2次补充货物，商铺中所有商品的剩余数量会补充至上限，从第3次补充货物开始，特殊商品将不再补充，只补充普通商品。补充货物后，此前未换取完毕商品的剩余数量不会保留，请守密人仔细思考后再选择补充货物噢~\n\n<Title:特遣纪录>\n1、活动期间，特遣纪录「血的颜色」可免费解锁。每隔2天会推出「血的颜色」新的调查事件，完成调查事件后可以获得钥令「神迹降临」、无垢之芯、调查徽章和守密人经验等调查奖励。\n2、活动结束后，「血的颜色」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「血的颜色」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、活动期间会推出限时成就奖励，守密人完成「血的颜色」的所有调查事件后，可以在活动成就中领取头像「以银钥之名：萨尔瓦多」！成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n\n"
  },
