  Activity_44716_ActivityTips = {
    Text = "<Title:活动规则>\n·「沉睡之主」活动开启期间，守密人可使用包含图鲁的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
