  Activity_51127_ActivityName = {
    Text = "故事的魔法·轻量复刻"
  },
  Activity_51127_ActivityPlot = {
    Text = "朵尔交待的任务，从来都不简单。\n即便她数次提醒大家「要玩得开心」，可首次带着一群唤醒体出门，守密人怎么能不胆战心惊？\n但，要记得「玩得开心」哦。"
  },
  Activity_51127_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「魔法剧本商店」"
  },
  Activity_51127_ActivityTips = {
    Text = "<Title:活动简介>\n1、玩法活动复刻「故事的魔法」限时开放，守密人可通过「魔法剧本商店」和「成就奖励」再次获得活动限定命轮「35mm 的魔法」与活动限定头像「以银钥之名：莉莉」！\n2、活动期间，「特遣纪录：故事的魔法」将限时免费解锁。\n\n<Title:活动时间>\n1、6 月 3 日 9:00 - 6 月 17 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、6 月 17 日 9:00 - 6 月 24 日 9:00（GMT+8），仅保留「魔法剧本商店」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title:剧本迷思>\n1、「剧本迷思」包含 9 个素材关卡，每天自动开放 1 个，开放后需通关前置特遣纪录关卡才可挑战。\n2、每次挑战将消耗 60 点灵啡肽，挑战成功将获得活动货币「飘零的灵感」和培养素材；本次活动素材关卡通关后即可支持重现。\n3、可以使用校友会助战和「共鸣：导演密码」来帮助你更轻松地通关。\n\n<Title:灵感加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「剧本迷思」关卡任务报酬中的「飘零的灵感」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「莉莉」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「跨越疼痛」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「35mm的魔法」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「灵感加成」以叠加的方式结算。\n\n<Title:共鸣：导演密码>\n1、守密人可以通过完成活动成就获取「演绎之心」。 \n2、消耗「演绎之心」，激活「共鸣：导演密码」，可以让守密人在活动玩法「剧本迷思」和「特遣纪录：故事的魔法」中变得更强，还可以提升完成「剧本迷思」挑战后获得的「飘零的灵感」和同调率奖励。\n\n<Title:成就奖励>\n1、完成成就任务可以获得活动限定头像「以银钥之名：莉莉」、活动货币「飘零的灵感」、银芯。\n2、包含 25 个任务：通关「剧本迷思」的每个关卡 1 次、使用每个界域队伍通关 「剧本迷思」 1/2 次、通关「特遣纪录：故事的魔法」每个调查事件 1 次、完成所有活动成就。\n\n<Title:特遣纪录>\n1、活动期间，「特遣纪录：故事的魔法」可免费解锁。\n2、在「特遣纪录：故事的魔法」中，守密人将使用包含剧情预设「莉莉」的特殊编队进行挑战。\n\n<Title:复刻补偿>\n1、此前已经解锁「特遣纪录：故事的魔法」的守密人，在本次复刻活动期间重新解锁时将会获得「飘零的灵感」×1000的补偿。\n此前已经获得活动限定头像「以银钥之名：莉莉」的守密人，重复获得时将自动转换为「飘零的灵感」×3000。\n此前已经获得激活共鸣材料「演绎之心」的守密人，每获得 1 个多余的「演绎之心」将自动转换为「蔷薇金券」×5000。\n"
  },
  Activity_51127_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_51611_ActivityName = {
    Text = "故事的魔法"
  },
  Activity_51611_ActivityTips = {
    Text = "<Title:参与条件>\n·完成「调查行动」2-9·普通后可参与。\n<Title:调查事件>\n·活动期间，每天会推出「故事的魔法」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「故事的魔法」的调查进度会保留，守密人可以在特遣纪录中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「故事的魔法」普通模式和完成「故事的魔法」的调查事件后，可以获得无垢之芯、贤者之石和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
  Activity_51888_ActivityName = {Text = "亵渎"},
  Activity_51905_ActivityName = {
    Text = "学园礼赠"
  },
  Activity_51905_ActivityTips = {
    Text = "活动规则：\n1、守密人每天登录后可以在「学园礼赠」中领取当日签到奖励。\n2、奖励将根据守密人累计登录依次解锁，当日签到奖励将在9点（GMT+8）刷新。"
  },
  Activity_52040_ActivityName = {
    Text = "沉渊之祀"
  },
  Activity_52040_ActivityPlot = {
    Text = "深海的倒影上，王的梦境消散，神的国度也已腐朽。\n她从旧日的幻梦中走来，走入未来坍塌的废墟。\n她询问深渊，深渊缄默不语。\n她向深渊祭祀，回应她的，只有她自己。"
  },
  Activity_52040_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「沉渊的回应」"
  },
  Activity_52040_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「神国诞临」、「王的谕旨」和「成就奖励」收集活动货币，活动货币可在「沉渊的回应」中用于进献从而获得道具奖励，包括活动限定SR命轮「深海的呼唤」、贤者之石、无垢之芯、流明之芯等。\n2、活动期间「异梦视界：亵渎」将免费开放。\n\n<Title:活动时间>\n1、6 月 17 日 9:00 - 7 月 1 日 9:00（GMT+8），所有活动内容均可参与。\n2、7 月 1 日 9:00 - 7 月 8 日 9:00（GMT+8），仅保留「沉渊的回应」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 神国诞临>\n1、「神国诞临」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「祀者之泪」、「祀者之血」和「祀者之髓」。双倍挑战时，需要消耗 240 灵啡肽，关卡任务报酬也会翻倍，同调率奖励不变。\n3、「成就奖励」完成度达到100%之后，解锁已通关关卡的「重现」功能。每次「重现」消耗 「灵啡肽」× 120 。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：海渊祭仪」来帮助你更轻松地通关。\n\n<Title: 祀物加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「神国诞临」关卡任务报酬中的「祀者之泪」、「祀者之血」和「祀者之髓」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「弥利亚姆」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「虔诚的伟力」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「深海的呼唤」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「祀物加成」以叠加的方式结算。\n\n<Title:共鸣：海渊祭仪>\n1、守密人可以通过完成活动成就获取「虔信之心」。 \n2、消耗「虔信之心」，激活「共鸣：海渊祭仪」，可以获得以下加成：\n（1）让守密人在活动玩法「神国诞临」中变得更强，挑战更加轻松。\n（2）提升完成「神国诞临」挑战后获得的活动货币。\n（3）激活活动玩法「王的谕旨」。\n\n<Title: 王的谕旨>\n·激活共鸣「祭献试炼」后，每小时自动获得60「祀者之泪」，最多储存 25 小时。\n\n<Title: 沉渊的回应>\n1、「沉渊的回应」共有三个祭坛，开启时间如下：\n·「莹泪祭坛」： 6 月 17 日 9 时开启。\n·「猩血祭坛」： 6 月 19 日 9 时开启。\n·「灵髓祭坛」： 6 月 21 日 9 时开启。\n2、每次进献祭品将消耗 500「祀者之泪」/「祀者之血」/「祀者之髓」，随机获得祭坛中的五个物品奖励。\n3、每个祭坛的物品奖励分为「神国的恩赐」和「凡庸的奖赏」两种，重置时可以使指定物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「神国的恩赐」无剩余数量后，守密人可以选择重置，重置后会将「神国的恩赐」和「凡庸的奖赏」的剩余数量重置至上限；也可以选择继续进献祭品，当「凡庸的奖赏」也无剩余数量后，须进行重置才可以继续进献祭品。\n（2）第3次开始重置：当「凡庸的奖赏」无剩余数量后才可以进行重置，重置会将「凡庸的奖赏」的剩余数量重置至上限，「神国的恩赐」不再重置。\n\n<Title: 异梦视界>\n1、「异梦视界」是全新的调查类型，相比通常的剧情演绎形式，「异梦视界」的将更侧重文字的表现，文字内容量也更多。\n2、在「异梦视界：亵渎」中，你将通过与弥利亚姆精神的链接，直接读取她的记忆，从而见证：尚为孩童的弥利亚姆一步步经历利莫里亚的苦难，在信仰中迷茫，在信仰中挣扎，最终走上了成为救世主与毁灭者的道路……\n3、活动期间「异梦视界：亵渎」将免费开放。每隔2天会推出新的事件，通关「异梦视界：亵渎」后可以在成就奖励中获得银芯、活动限定SR命轮「深海的呼唤」等奖励，成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n4、活动结束后，「异梦视界：亵渎」的调查进度会保留，如果活动期间未解锁「异梦视界：亵渎」，活动结束后仍然可以消耗「现实起点」×7解锁。\n5、无论是否在活动期间，通关「异梦视界：亵渎」后都可以获得「钥令：海之祭」。\n\n\n\n"
  },
