  Activity_53727_ActivityName = {Text = "返校日"},
  Activity_53727_ActivityTips = {
    Text = "<Title:活动简介>\n·「返校日」任务分为4组，分别在活动开启第1、2、3、4天解锁。\n·守密人可以通过完成「返校日」任务获得「返校邀约」。\n·使用「返校邀约」可以在「返校商店」中兑换丰厚奖励。"
  },
