  },
  Activity_53728_ActivityTips = {
    Text = "<Title:活动简介>\n·「助力新程」活动期间，守密人通关「制剂淬炼」「浑浊残像」「海渊残像」「器质残像」「维度残像」「混沌集群」「波纳佩之墟」「蠕虫之所」「史瓦西喉」后，「蔷薇金券」和素材奖励将会翻倍，每天总共可享受6次。\n·当日未使用完毕的双倍奖励次数将在次日9点（GMT+8）清空，请守密人记得及时使用喔~"
  },
  Activity_53729_ActivityName = {
