  },
  Activity_53729_ActivityTips = {
    Text = "<Title:活动简介>\n·守密人每天登录后可以在「返校报道」中领取当日签到奖励。\n·奖励将根据守密人累计登录依次解锁，当日签到奖励将在9点（GMT+8）刷新。"
