    Text = "玩法活动限时开启！"
  },
  Activity_54375_ActivityName = {
    Text = "蔷薇礼赞"
  },
  Activity_54375_ActivityPlot = {
    Text = "女士们，先生们。\n温和的良夜已经拉开帷幕，准备好手边的佳酿吧。\n这是一个漫长的故事，且听我们慢慢道来……"
  },
  Activity_54375_ActivityTips = {
    Text = "<Title:参与条件>\n·完成「调查行动」2-9·普通后可参与。\n<Title:调查事件>\n·活动期间，每天会推出「蔷薇礼赞」中一个新的调查事件，守密人无需消耗物资即可解锁进行调查，完成调查事件后可以获得无垢之芯、调查徽章和守密人经验等调查奖励。\n·活动结束后，「蔷薇礼赞」的调查进度会保留，守密人可以在特遣纪录中消耗融蚀之珠解锁未解锁的调查，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。<Title:限时奖励>\n·活动期间会推出限时奖励，守密人通关「蔷薇礼赞」普通模式和完成「蔷薇礼赞」的调查事件后，可以获得无垢之芯、贤者之石和银芯奖励！限时奖励仅在活动期间开启，活动结束后将无法完成和领取。"
  },
