  Activity_54596_ActivityName = {
    Text = "智识赠礼"
  },
  Activity_54596_ActivityTips = {
    Text = "<Title:活动简介>\n1、守密人完成活动指定任务后，可领取「原质乐园」、「轮转之书」、「原型视界」、「循环母版」、「灵魂回溯之芯」、「命途回溯之芯」，以及「忘却篇」限定唤醒体与命轮、「星辰篇」限定唤醒体与命轮等丰厚奖励，更有活动限定头像框「银白之矩」、守密人经验加速等专属奖励！\n2、本活动永久开放。完成活动中所有任务并领取完奖励后，第二天9:00（GMT+8）后本活动结束并不再展示。\n\n<Title:至高礼赞>\n1、完成活动指定任务可获得「至高礼赞」效果，使守密人经验获得加速，最高可达 100%。多个「至高礼赞」效果同时存在时，取最高的加速效果。\n2、解锁或获得更高级的「至高礼赞」效果时，会按照加速比例和当前可被加速的守密人经验总量，立即获得额外的守密人经验。\n3、解锁「至高礼赞」后，守密人每次获得守密人经验时，都将获得对应加速比例的额外守密人经验。\n4、请注意，「至高礼赞」带来的额外守密人经验不会计入可被加速的守密人经验总量。\n5、当前可被加速的守密人经验总量：{s1}。\n6、加速已累计获得额外守密人经验：{s2}（{s3}%）。"
  },
  Activity_55110_ActivityName = {
    Text = "在春天凋零以前"
  },
  Activity_55110_ActivityPlot = {
    Text = "少女们的笑声响起，回荡在大火尚未燃起的花园。\n为这美丽的往昔驻足吧，我的朋友。\n听尚未凋零的春天，轻声讲述过去的故事。"
  },
  Activity_55110_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「柯蕾特的花房」"
  },
  Activity_55110_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「花园往事」、「缪斯之吻」和「成就奖励」收集三种「诗文」，「诗文」可在「柯蕾特的花房」中用于交换从而获得道具奖励，包括活动限定SR命轮「往昔的花与诗」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间「特遣纪录：玫瑰的栖居」将免费开放。\n\n<Title:活动时间>\n1、7 月 15 日 9:00 - 7 月 29 日 9:00（GMT+8），所有活动内容均可参与。\n2、7 月 29 日 9:00 - 8 月 5 日 9:00（GMT+8），仅保留「柯蕾特的花房」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 花园往事>\n1、「花园往事」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「惆怅的诗文」、「遗憾的诗文」和「欢欣的诗文」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：花园挽歌」来帮助你更轻松地通关。\n5、关卡解锁后第2天，解锁该关卡的癫狂难度。完成癫狂难度首通可获得丰厚的活动货币奖励。\n6、请注意：癫狂难度挑战不消耗灵啡肽，不可重现，且首通后重复挑战不会再获得活动货币奖励。\n\n<Title: 诗文加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「花园往事」关卡任务报酬中的「惆怅的诗文」、「遗憾的诗文」和「欢欣的诗文」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「奥尔拉」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「诗笺的句尾」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「往昔的花与诗」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「诗文加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「诗文加成」影响。\n\n<Title:共鸣：花园挽歌>\n1、守密人可以通过完成活动成就获取「灰烬之心」。 \n2、消耗「灰烬之心」，激活「共鸣：花园挽歌」，可以获得以下加成：\n（1）让守密人在活动玩法「花园往事」中变得更强，挑战更加轻松。\n（2）提升完成「花园往事」挑战后获得的活动货币。\n（3）激活活动玩法「缪斯之吻」。\n\n<Title: 缪斯之吻>\n·激活共鸣「万物生长」后，每小时自动获得60「惆怅的诗文」，最多储存 25 小时。\n·激活共鸣「以诗换花」后，「缪斯之吻」每小时可额外获得60「遗憾的诗文」。\n\n<Title: 柯蕾特的花房>\n1、「柯蕾特的花房」共有三个花圃，开启时间如下：\n·「鸢尾花圃」： 7 月 15 日 9 时开启。\n·「桔梗花圃」： 7 月 17 日 9 时开启。\n·「蔷薇花圃」： 7 月 19 日 9 时开启。\n2、每次交换将消耗 1000「惆怅的诗文」/「遗憾的诗文」/「欢欣的诗文」，随机获得花圃中的五个物品奖励。\n3、每个花圃的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n4、8 月 5 日 9:00（GMT+8）后，剩余未交换的「诗文」将按照每200个兑换「蔷薇金券×5000」的比例进行回收，请守密人注意查收邮件。\n\n<Title: 特遣纪录>\n1、活动期间「特遣纪录：玫瑰的栖居」将免费开放。每隔2天会推出新的事件，通关「特遣纪录：玫瑰的栖居」后可以在成就奖励中获得银芯、活动限定SR命轮「往昔的花与诗」等奖励，成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n2、活动结束后，「特遣纪录：玫瑰的栖居」的调查进度会保留，如果活动期间未解锁「特遣纪录：玫瑰的栖居」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「特遣纪录：玫瑰的栖居」后都可以获得「钥令：春天的献诗」。"
  },
