  },
  Activity_56427_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「圣堂之路」、「市民的善意」和「成就奖励」收集活动货币「义卖券」，「义卖券」可在「圣堂义卖现场」中换取随机商品，包括活动限定SR命轮「镜中人」、无垢之芯、流明之芯等。\n2、活动期间，「特遣纪录：血的颜色」将免费开放。完成活动成就还能获得活动限定头像「以银钥之名：萨尔瓦多」！\n\n<Title:活动时间>\n1、8 月 26 日 9:00 - 9 月 9 日 9:00（GMT+8），所有活动内容均可参与。\n2、9 月 9 日 9:00 - 9 月 16 日 9:00（GMT+8），仅保留「圣堂义卖现场」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title:圣堂之路>\n1、「圣堂之路」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「义卖券」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：灵魂的岔路」来帮助你更轻松地过关。\n\n<Title:辉光加成>\n1、在「灵魂辉光」的影响下，守密人拥有特定唤醒体或命轮（不要求上阵）可以使可以使「圣堂之路」关卡任务报酬中的「义卖券」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「萨尔瓦多」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「神言石板」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「镜中人」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「辉光加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「辉光加成」影响。\n\n<Title:共鸣：灵魂的岔路>\n1、守密人可以通过完成活动成就获取「忏悔之心」。 \n2、消耗「忏悔之心」，激活「共鸣：灵魂的岔路」，可以获得以下加成：\n（1）让守密人在活动玩法「圣堂之路」和「特遣纪录：血的颜色」中变得更强，挑战更加轻松。\n（2）提升完成「圣堂之路」挑战后获得的同调率。\n（3）激活活动玩法「市民的善意」。\n\n<Title:市民的善意>\n1、激活共鸣「轻松的方式」后，每小时自动获得60「义卖券」，最多储存 25 小时。\n2、激活共鸣「赎罪，赎罪」后，每小时额外自动获得 1800 蔷薇金券。\n\n<Title: 圣堂义卖现场>\n1、「圣堂义卖现场」共有三个商铺，开启时间如下：\n·「格雷太太的小店」： 8 月 26 日 9 时开启。\n·「大约翰的神奇义卖」： 8 月 29 日 9 时开启。\n·「史密斯特卖」： 9 月 1 日 9 时开启。\n2、每次交换将消耗 1000「义卖券」，随机获得商铺中的五个物品奖励。\n3、每个商铺的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n4、9 月 16 日 9:00（GMT+8）后，剩余未交换的「义卖券」将按照每200个兑换「蔷薇金券×5000」的比例进行回收，请守密人注意查收邮件。\n\n<Title: 特遣纪录>\n1、活动期间「特遣纪录：血的颜色」将免费开放。\n2、活动结束后，「特遣纪录：血的颜色」的调查进度会保留，如果活动期间未解锁「特遣纪录：血的颜色」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「特遣纪录：血的颜色」后都可以获得「钥令：神迹降临」。\n\n<Title:复刻补偿>\n1、此前已经解锁「特遣纪录：血的颜色」的守密人，在本次复刻活动期间重新解锁时将会获得「义卖券」×700的补偿。\n2、此前已经获得活动限定头像「以银钥之名：萨尔瓦多」的守密人，重复获得时将自动转换为「义卖券」×2000。\n3、此前已经获得激活共鸣材料「忏悔之心」的守密人，每获得 1 个多余的「忏悔之心」将自动转换为「蔷薇金券」×5000。\n"
  },
