  Activity_56431_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「黑暗子宫」和「成就奖励」收集三种「胚胎」，「胚胎」可在「圣胎孵化」中兑换道具奖励，包括活动限定SR命轮「冰川下的沉眠」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间，完成「成就奖励」的任务可获得活动限定头像「以银钥之名：戈利亚」、活动限定SR命轮「冰川下的沉眠」和大量「胚胎」。\n\n<Title:活动时间>\n1、7 月 29 日 9:00 - 8 月 12 日 9:00（GMT+8），所有活动内容均可参与。\n2、8 月 12 日 9:00 - 8 月 19 日 9:00（GMT+8），仅保留「圣胎孵化」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 黑暗子宫>\n1、「黑暗子宫」包含 7 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「无识之胚」、「无欲之胚」和「无厌之胚」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n5、通关关卡任意难度后，解锁该关卡的癫狂难度。完成癫狂难度首通可获得丰厚的活动货币奖励。\n6、请注意：癫狂难度挑战不消耗灵啡肽，不可重现，且首通后重复挑战不会再获得活动货币奖励。\n\n<Title: 胚胎加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「黑暗子宫」关卡任务报酬中的「无识之胚」、「无欲之胚」和「无厌之胚」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「墨菲」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「隐秘的诞生」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「冰川下的沉眠」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「胚胎加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「胚胎加成」影响。\n\n<Title: 圣胎孵化>\n1、「圣胎孵化」仅在 7 月 29 日 9:00 - 8 月 19 日 9:00（GMT+8）期间开放。\n2、8 月 19 日 9:00（GMT+8）后，剩余未兑换的「胚胎」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
  Activity_56431_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_56432_ActivityName = {
    Text = "雪山消融之时"
  },
  Activity_56432_ActivityPlot = {
    Text = "艾尔沃斯的冰雪终年不化，正如她的仇恨。\n当未来与过去的双手交叠，战士将高举剑刃，向命运发起复仇的冲锋。\n当她迎向黑色的浪涛，你是她的旌旗。"
  },
  Activity_56432_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「山峦巨口」"
  },
  Activity_56432_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「野兽雄心」和「成就奖励」收集三种「花苞」，「花苞」可在「山峦巨口」中用于交换从而获得道具奖励，包括活动限定SR命轮「待到雪山消融」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间「特遣纪录：艾尔沃斯的归人」将免费开放。\n\n<Title:活动时间>\n1、10 月 7 日 9:00 - 10 月 21 日 9:00（GMT+8），所有活动内容均可参与。\n2、10 月 21 日 9:00 - 10 月 28 日 9:00（GMT+8），仅保留「山峦巨口」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 野兽雄心>\n1、「野兽雄心」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「寒冻花苞」、「银霜花苞」和「日光花苞」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：吞噬山脉」来帮助你更轻松地通关。\n5、关卡解锁后第2天，解锁该关卡的癫狂难度。完成癫狂难度首通可获得丰厚的活动货币奖励。\n6、请注意：癫狂难度挑战不消耗灵啡肽，不可重现，且首通后重复挑战不会再获得活动货币奖励。\n\n<Title: 花苞加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「野兽雄心」关卡任务报酬中的「寒冻花苞」、「银霜花苞」和「日光花苞」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「血链·希洛」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「沉入殷红」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「待到雪山消融」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「花苞加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「花苞加成」影响。\n\n<Title:共鸣：吞噬山脉>\n1、守密人可以通过完成活动成就获取「吞噬之心」。 \n2、消耗「吞噬之心」，激活「共鸣：吞噬山脉」，可以让守密人在活动玩法「野兽雄心」中变得更强，挑战更加轻松。\n\n<Title: 山峦巨口>\n1、「山峦巨口」共有三个交换商店，开启时间如下：\n·「吞食的野心」： 10 月 7 日 9 时开启。\n·「复仇的战意」： 10 月 9 日 9 时开启。\n·「重生的希冀」： 10 月 11 日 9 时开启。\n2、每次交换将消耗 1000「寒冻花苞」/「银霜花苞」/「日光花苞」，随机获得交换商店中的五个物品奖励。\n3、每个交换商店的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 2 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 3 次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n4、10 月 28 日 9:00（GMT+8）后，剩余未交换的「花苞」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。\n\n<Title: 特遣纪录>\n1、活动期间「特遣纪录：艾尔沃斯的归人」将免费开放。每隔 2 天会推出新的事件，通关「特遣纪录：艾尔沃斯的归人」后可以在成就奖励中获得银芯、活动限定SR命轮「待到雪山消融」等奖励，成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n2、活动结束后，「特遣纪录：艾尔沃斯的归人」的调查进度会保留，如果活动期间未解锁「特遣纪录：艾尔沃斯的归人」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「特遣纪录：艾尔沃斯的归人」后都可以获得「钥令：群山的觉悟」。"
  },
