  Activity_56434_ActivityPlot = {
    Text = "无人知晓她在门扉前静默的年岁。\n她本无意投身任何一个具象世界，不应为任何时空连续体裹挟精神，不容任何事物扰动穷极之门的平稳。\n直到她与你的目光相触的刹那。"
