  Activity_61156_ActivityName = {
    Text = "终焉纪行"
  },
  Activity_61156_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「终焉纪行」中领取奖励。\n2、「终焉纪行」永久开放。\n3、解锁「高级纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_61369_ActivityName = {
    Text = "渐进乐律"
  },
  Activity_61369_ActivityPlot = {
    Text = "守密人可以从以下限定命轮中任选其一唤醒！"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:简介>\n黑池波云诡谲，命轮往复流转，在哈姆林的乐音牵引下，无限乐律齐奏，汇成你所跋涉的历程之命轮。愿它们的助力能陪伴你直至终末奏鸣的休止符。\n\n<Title:活动规则>\n·活动期间只需登录一天，即可在以下12个限定命轮中任选其一唤醒，包括：「神王的颂歌」、「至为珍贵的藏品」、「以蔷薇之名」、「跨越疼痛」、「隐秘的诞生」、「女王的戒律」、「神言石板」、「畸体回噬」、「虔诚的伟力」、「诗笺的句尾」、「慈悲的哺育」、「好运时间」。"
  },
  Activity_61369_BannerText = {
    Text = "限定命轮免费领取"
  },
  Activity_61370_ActivityName = {
    Text = "纯银的初心"
  },
  Activity_61370_ActivityPlot = {
    Text = "每日登录可领取纪念限定SSR命轮「纯银之心」，总计可领取16个！"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:简介>\n无论世界如何倾覆，只要每个人都守护着最初的、澄澈的纯银之心，故事终会往复循环，新的生命将在荒芜的大地上重新诞生。\n\n<Title:活动规则>\n·活动期间，守密人每天登录后可以在「纯银的初心」中领取纪念限定 SSR 命轮「纯银的初心」，总计可领取 16 次。\n·奖励将根据守密人累计登录依次解锁，当日登录奖励将在9点（GMT+8）刷新。"
  },
  Activity_61370_BannerText = {
    Text = "限定SSR命轮免费领取"
  },
  Activity_61371_ActivityName = {
    Text = "六翼满开之愿"
  },
  Activity_61371_ActivityPlot = {
    Text = "黑池动荡之中，来自无限维度的银芯通过维度罅隙散落在黑池之畔。塔薇将它们悉心收拢，置于黑池一角。纵然这些银芯不能阻止融蚀蔓延，但其中蕴藏的思念与心意永远光华璀璨。"
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:简介>\n黑池动荡之中，来自无限维度的银芯通过维度罅隙散落在黑池之畔。塔薇将它们悉心收拢，置于黑池一角。纵然这些银芯不能阻止融蚀蔓延，但其中蕴藏的思念与心意永远光华璀璨。\n\n<Title:活动规则>\n·活动期间，守密人每天登录后可以在活动中领取「银芯」× 1000，最多可以领取 6 次。\n·活动期间，守密人累计登录第 7 天，更可直接领取当期限定唤醒体「塔薇」！\n·奖励将根据守密人累计登录依次解锁，当日登录奖励将在9点（GMT+8）刷新。"
  },
  Activity_61371_BannerText = {
    Text = "签到领取超多银芯"
  },
