  Activity_65387_ActivityName = {
    Text = "校猫的歉意"
  },
  Activity_65387_ActivityPlot = {
    Text = "近期由于校方防护措施漏洞，导致<Del:「临时文本、红点」>融蚀侵扰校园的情况越来越多，为广大学子带来了诸多不便。因此校务处特地设立了多处补给点，为同学们发放物资作为补偿。（鉴于设施管理失误的责任，本次补给物资完全由校猫负责搬运。）"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:简介>\n近期由于校方防护措施漏洞，导致<Del:「临时文本、红点」>融蚀侵扰校园的情况越来越多，为广大学子带来了诸多不便。因此校务处特地设立了多处补给点，为同学们发放物资作为补偿。（鉴于设施管理失误的责任，本次补给物资完全由校猫负责搬运。）\n\n<Title:活动规则>\n·活动期间，守密人每天登录后可以在「校猫的歉意」中领取「银芯」× 500，最多可以领取 5 次。\n·奖励将根据守密人累计登录依次解锁，当日登录奖励将在9点（GMT+8）刷新。"
  },
  Activity_65387_BannerText = {
    Text = "签到领取银芯"
  },
  Activity_65502_ActivityName = {
    Text = "渐进乐律·双重奏"
  },
  Activity_65502_ActivityPlot = {
    Text = "守密人可以从以下限定命轮中任选其一唤醒！"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:简介>\n黑池波云诡谲，命轮往复流转，在哈姆林的乐音牵引下，无限乐律齐奏，汇成你所跋涉的历程之命轮。愿它们的助力能陪伴你直至终末奏鸣的休止符。\n\n<Title:活动规则>\n·活动期间只需登录一天，即可在以下12个限定命轮中任选其一唤醒，包括：「神王的颂歌」、「至为珍贵的藏品」、「以蔷薇之名」、「跨越疼痛」、「隐秘的诞生」、「女王的戒律」、「神言石板」、「畸体回噬」、「虔诚的伟力」、「诗笺的句尾」、「慈悲的哺育」、「好运时间」。"
  },
  Activity_65502_BannerText = {
    Text = "限定命轮免费领取"
  },
