  Activity_66375_ActivityName = {
    Text = "决胜：原初之影"
  },
  Activity_66375_ActivityPlot = {
    Text = "祂的目光掠过万千维度，与祂对视的，是万千银色的身影。 \n他们渺小，脆弱。他们为铭记而战，至死方休。"
  },
  Activity_66375_ActivityStageEndContent = {
    Text = "活动已达成，可前往继续调查。"
  },
  Activity_66375_ActivityTips = {
    Text = "<Title: 共战原初>\n·「共战原初」包含 7 个不可重现、直接挑战原初之视的关卡，活动首日开放前 3 个，之后每 3 天开放 1 个。\n·每次挑战战胜对应的原初之视后，即可获得对应奖励。\n·每种原初之视均有大量分身，每当某个种类的原初之视被任何守密人挑战胜利时，该类型原初之视的「世界残余数量」就会减少 1，当该类型原初之视的所有分身被消灭后，相应的关卡就会关闭，无法再次挑战。\n·所有关卡都受到「融灾黑潮·终末」的影响，但是每个关卡会提供不同的「纯银之芯」造物，将会为你提供强大的加成。此外，每个关卡还会提供「全知之眼」造物，将使塔薇在战斗开始时获得 120 狂气，塔薇所有造成的伤害、护盾、回复生命效果提高 50%。\n·所有关卡必须选择助战，整个活动中，每个互相关注的守密人只能为你提供一次助战。由于使用助战，因此实际同调率奖励会在奖励基础上再提高 50%。\n·守密人需要至少完成调查行动 2-9 才可以参与该活动。\n\n<Title:调查行动：终章>\n·每种原初之视的本体仍然需要在调查行动 9-5 至 9-11 中由你自己来击败。这些特殊关卡没有成就、没有星数，也没有「全知之眼」造物的帮助、也无法使用助战，同时更加困难。\n·在「共战原初」活动结束后即可解锁「调查行动：终章」的后续关卡。与其他守密人共同消灭各种原初之视的所有分身后，可以提前解锁调查行动 9-5 至 9-11 中对应的关卡。"
  },
  Activity_66375_BannerText = {
    Text = "特别活动限时开启！"
  },
  Activity_66908_ActivityName = {
    Text = "丰穰之息"
  },
  Activity_66908_ActivityTips = {
    Text = "<Title:活动规则>\n·「丰穰之息」活动开启期间，守密人可使用包含泰旖丝的系统预设队伍，无限次体验指定关卡。\n·体验活动关卡时，无法调整编队中的唤醒体。\n<Title:活动奖励>\n·首次达成关卡挑战后，可以在活动界面领取试玩奖励。"
  },
  Activity_67077_ActivityName = {
    Text = "历程追思献礼Ⅸ"
  },
  Activity_67077_ActivityPlot = {
    Text = "一段记忆尘封归档，一段历程载入过往。追思之时，勿忘献上崇敬之礼。"
  },
  Activity_67718_ActivityName = {
    Text = "在春天凋零以前·复刻"
  },
  Activity_67718_ActivityPlot = {
    Text = "少女们的笑声响起，回荡在大火尚未燃起的花园。\n为这美丽的往昔驻足吧，我的朋友。\n听尚未凋零的春天，轻声讲述过去的故事。"
  },
  Activity_67718_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「柯蕾特的花房」"
  },
  Activity_67718_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「花园往事」、「缪斯之吻」和「成就奖励」收集三种「诗文」，「诗文」可在「柯蕾特的花房」中用于交换从而获得道具奖励，包括活动限定SR命轮「往昔的花与诗」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间「特遣纪录：玫瑰的栖居」将免费开放。\n\n<Title:活动时间>\n1、8 月 10 日 9:00 - 9 月 7 日 9:00（GMT+8），所有活动内容均可参与。\n2、9 月 7 日 9:00 - 9 月 14 日 9:00（GMT+8），仅保留「柯蕾特的花房」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 花园往事>\n1、「花园往事」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币「惆怅的诗文」、「遗憾的诗文」和「欢欣的诗文」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：花园挽歌」来帮助你更轻松地通关。\n5、请注意：癫狂难度挑战不消耗灵啡肽，不可重现，且首通后重复挑战不会再获得活动货币奖励。\n\n<Title: 诗文加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「花园往事」关卡任务报酬中的「惆怅的诗文」、「遗憾的诗文」和「欢欣的诗文」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「奥尔拉」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「诗笺的句尾」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「往昔的花与诗」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「诗文加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「诗文加成」影响。\n\n<Title:共鸣：花园挽歌>\n1、守密人可以通过完成活动成就获取「灰烬之心」。 \n2、消耗「灰烬之心」，激活「共鸣：花园挽歌」，可以获得以下加成：\n（1）让守密人在活动玩法「花园往事」中变得更强，挑战更加轻松。\n（2）提升完成「花园往事」挑战后获得的活动货币。\n（3）激活活动玩法「缪斯之吻」。\n\n<Title: 缪斯之吻>\n·激活共鸣「万物生长」后，每小时自动获得「惆怅的诗文」× 60，最多储存 25 小时。\n·激活共鸣「以诗换花」后，「缪斯之吻」每小时可额外获得「遗憾的诗文」× 60。\n\n<Title: 柯蕾特的花房>\n1、「柯蕾特的花房」共有三个花圃，开启时间如下：\n·「鸢尾花圃」： 8 月 10 日 9 时开启。\n·「桔梗花圃」： 8 月 12 日 9 时开启。\n·「蔷薇花圃」： 8 月 14 日 9 时开启。\n2、每次交换将消耗 「惆怅的诗文」/「遗憾的诗文」/「欢欣的诗文」× 750，随机获得花圃中的五个物品奖励。\n3、每个花圃的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n4、9 月 14 日 9:00（GMT+8）后，剩余未交换的「诗文」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。\n\n<Title: 特遣纪录>\n1、活动期间「特遣纪录：玫瑰的栖居」将免费开放。每隔2天会推出新的事件，通关「特遣纪录：玫瑰的栖居」后可以在成就奖励中获得银芯、活动限定SR命轮「往昔的花与诗」等奖励，成就奖励仅在活动期间开启，活动结束后将无法完成和领取。\n2、活动结束后，「特遣纪录：玫瑰的栖居」的调查进度会保留，如果活动期间未解锁「特遣纪录：玫瑰的栖居」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「特遣纪录：玫瑰的栖居」后都可以获得「钥令：春天的献诗」。"
  },
