  Activity_67733_ActivityName = {
    Text = "沉渊之祀·复刻"
  },
  Activity_67733_ActivityPlot = {
    Text = "深海的倒影上，王的梦境消散，神的国度也已腐朽。\n她从旧日的幻梦中走来，走入未来坍塌的废墟。\n她询问深渊，深渊缄默不语。\n她向深渊祭祀，回应她的，只有她自己。"
  },
  Activity_67733_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「沉渊的回应」"
  },
  Activity_67733_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「神国诞临」、「王的谕旨」和「成就奖励」收集活动货币，活动货币可在「沉渊的回应」中用于进献从而获得道具奖励，包括活动限定SR命轮「深海的呼唤」、贤者之石、无垢之芯、流明之芯等。\n2、活动期间「异梦视界：亵渎」将免费开放，完成活动成就还能获得活动限定头像「以银钥之名：弥利亚姆」！。\n\n<Title:活动时间>\n1、7 月 28 日 9:00 - 8 月 18 日 9:00（GMT+8），所有活动内容均可参与。\n2、8 月 18 日 9:00 - 8 月 25 日 9:00（GMT+8），仅保留「沉渊的回应」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 神国诞临>\n1、「神国诞临」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：海渊祭仪」来帮助你更轻松地通关。\n\n<Title: 祀物加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「神国诞临」关卡任务报酬中的「祀者之泪」、「祀者之血」和「祀者之髓」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「弥利亚姆」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「虔诚的伟力」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「深海的呼唤」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「祀物加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「祀物加成」影响。\n\n<Title:共鸣：海渊祭仪>\n1、守密人可以通过完成活动成就获取「虔信之心」。 \n2、消耗「虔信之心」，激活「共鸣：海渊祭仪」，可以获得以下加成：\n（1）让守密人在活动玩法「神国诞临」中变得更强，挑战更加轻松。\n（2）提升完成「神国诞临」挑战后获得的活动货币。\n（3）激活活动玩法「王的谕旨」。\n\n<Title: 王的谕旨>\n·激活共鸣「祭献试炼」后，每小时自动获得60「祀者之泪」，最多储存 25 小时。\n\n<Title: 沉渊的回应>\n1、「沉渊的回应」共有三个祭坛，开启时间如下：\n·「莹泪祭坛」： 7 月 28 日 9 时 ~8 月 25 日 9 时。\n·「猩血祭坛」： 7 月 30 日 9 时 ~ 8 月 25 日 9 时。\n·「灵髓祭坛」： 8 月 1 日 9 时 ~ 8 月 25 日 9 时。\n2、每次进献祭品将消耗 1000「祀者之泪」/「祀者之血」/「祀者之髓」，随机获得祭坛中的五个物品奖励。\n3、每个祭坛的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使指定物品奖励的剩余数量重置至上限，具体规则为：\n（1）前3次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续进献祭品，当「普通物品」也无剩余数量后，须进行重置才可以继续进献祭品。\n（2）第4次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title: 异梦视界>\n1、活动期间「异梦视界：亵渎」将免费开放。\n2、活动结束后，「异梦视界：亵渎」的调查进度会保留，如果活动期间未解锁「异梦视界：亵渎」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：亵渎」后都可以获得「钥令：海之祭」。\n\n<Title:复刻补偿>\n1、此前已经解锁「异梦视界：亵渎」的守密人，在本次复刻活动期间重新解锁时将会获得「祀者之泪」×700的补偿。\n2、此前已经获得活动限定头像「以银钥之名：弥利亚姆」的守密人，重复获得时将自动转换为「无形者的请柬」×1。\n3、此前已经获得激活共鸣材料「虔信之心」的守密人，每获得 1 个多余的「虔信之心」将自动转换为「蔷薇金券」×5000。\n"
  },
