  Activity_67741_ActivityPlot = {
    Text = "朵尔交待的任务，从来都不简单。\n即便她数次提醒大家「要玩得开心」，可首次带着一群唤醒体出门，守密人怎么能不胆战心惊？\n但，要记得「玩得开心」哦。"
