  Activity_67741_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「魔法剧本商店」"
  },
  Activity_67741_ActivityTips = {
    Text = "<Title:活动简介>\n1、玩法活动复刻「故事的魔法」限时开放，守密人可通过「魔法剧本商店」和「成就奖励」再次获得活动限定命轮「35mm 的魔法」与活动限定头像「以银钥之名：莉莉」！\n2、活动期间，「特遣纪录：故事的魔法」将限时免费解锁。\n\n<Title:剧本迷思>\n1、「剧本迷思」包含 9 个素材关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战和「共鸣：导演密码」来帮助你更轻松地通关。\n\n<Title:灵感加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「剧本迷思」关卡任务报酬中的「飘零的灵感」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「莉莉」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「跨越疼痛」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「35mm的魔法」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「灵感加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title:共鸣：导演密码>\n1、守密人可以通过完成活动成就获取「演绎之心」。 \n2、消耗「演绎之心」，激活「共鸣：导演密码」，可以让守密人在活动玩法「剧本迷思」和「特遣纪录：故事的魔法」中变得更强。\n\n<Title:复刻补偿>\n1、此前已经解锁「特遣纪录：故事的魔法」的守密人，在本次复刻活动期间重新解锁时将会获得「飘零的灵感」×700的补偿。\n此前已经获得活动限定头像「以银钥之名：莉莉」的守密人，重复获得时将自动转换为「飘零的灵感」×2000。\n此前已经获得激活共鸣材料「演绎之心」的守密人，每获得 1 个多余的「演绎之心」将自动转换为「蔷薇金券」×5000。\n\n<Title:活动时间>\n1、1 月 13 日 9:00 - 1 月 27 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、1 月 27 日 9:00 - 2 月 3 日 9:00（GMT+8），仅保留「魔法剧本商店」和「成就奖励」，其他内容均已结束不可参与。\n3、2 月 3 日 9:00（GMT+8）后，剩余未兑换的「飘零的灵感」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
  Activity_67741_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_67742_ActivityName = {
    Text = "与蔷薇书·复刻"
  },
  Activity_67742_ActivityPlot = {
    Text = "华丽的金钻，耀眼的珠光……\n无数浮华的装点为她赢得了女皇般虚妄的想象\n现在，她决心将这份虚妄维持到永远。"
  },
  Activity_67742_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「金红庆典」"
  },
  Activity_67742_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「蔷薇忆事」和「成就奖励」收集活动货币「通灵鸟羽扇」，「通灵鸟羽扇」可在「金红庆典」中兑换丰厚奖励，包括活动限定SR命轮「百万蒙宠之眼」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间，完成「成就奖励」的任务可获得活动限定头像「以银钥之名：索蕾尔」、活动限定SR命轮「百万蒙宠之眼」、银芯和大量活动货币「通灵鸟羽扇」。\n3、活动期间，「特遣纪录：蔷薇礼赞」将免费开放。\n\n<Title: 蔷薇忆事>\n1、「蔷薇忆事」包含 9 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战不同的关卡除了获得不同的素材掉落外，还将获得活动货币「通灵鸟羽扇」。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title: 羽扇加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「蔷薇忆事」关卡任务报酬中的「通灵鸟羽扇」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「索蕾尔」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「以蔷薇之名」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「百万蒙宠之眼」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「羽扇加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title:复刻补偿>\n1、活动期间，此前已经解锁「特遣纪录：蔷薇礼赞」的守密人，重新解锁将会获得「通灵鸟羽扇」×700的补偿。\n此前已经获得活动限定头像「以银钥之名：索蕾尔」的守密人，重复获得时将自动转换为「通灵鸟羽扇」×2000。\n\n<Title:活动时间>\n1、1 月 27 日 9:00 - 2 月 10 日 9:00（GMT+8），所有活动内容均可参与。\n2、2 月 10 日 9:00 - 2 月 17 日 9:00（GMT+8），仅保留「金红庆典」和「成就奖励」，其他内容均已结束不可参与。\n3、2 月 17 日 9:00（GMT+8）后，剩余未兑换的「通灵鸟羽扇」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
