  },
  Activity_67746_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「最终测试」和「成就奖励」收集活动货币「终末指针」，「终末指针」可在「回声」中兑换丰厚奖励，包括活动限定SR命轮「真理之门」、「无垢之芯」、「流明之芯」、「贤石碎屑」、「拟态凝晶」等。\n2、活动期间，完成「成就奖励」的任务可获得活动限定头像「以银钥之名：塔薇」、活动限定SR命轮「真理之门」、银芯和大量活动货币「终末指针」。\n\n<Title:活动时间>\n1、11 月 3 日 9:00 - 11 月 17 日 9:00（GMT+8），所有活动内容均可参与。\n2、11 月 17 日 9:00 - 11 月 24 日 9:00（GMT+8），仅保留「回声」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 最终测试>\n1、「最终测试」包含 9 个关卡，每天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战不同的关卡除了获得不同的素材掉落外，还将获得活动货币「终末指针」。\n3、本次活动关卡为直接战斗的素材关卡，通关后可重现！每次「重现」消耗 「灵啡肽」× 120 。\n4、请注意：使用「重现」功能时，无法获得同调率。\n\n<Title: 终末指针加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「最终测试」关卡任务报酬中的「终末指针」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「塔薇」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「隐世的转轮」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「真理之门」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「终末指针加成」以叠加的方式结算。\n3、特别的，癫狂难度首通挑战奖励不会受到「终末指针加成」影响。\n\n<Title: 回声>\n1、「回声」仅在 11 月 3 日 9:00 - 11 月 24 日 9:00（GMT+8）期间开放。\n2、11 月 24 日 9:00（GMT+8）后，剩余未兑换的「终末指针」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
