  Activity_68349_ActivityName = {
    Text = "超越星辰·限时预购"
  },
  Activity_68349_ActivityTips = {
    Text = "<Title: 超越星辰·限时预购>\n·本次限时预购活动包含 8 个礼包，其中首个礼包可直接免费领取，第 2-8 个礼包需要购买「超越星辰·限时预购」后方可领取。\n·购买「超越星辰·限时预购」后可立即领取第 2 个礼包奖励；后续礼包需要分别等待一定时间后才可领取。\n·「超越星辰·限时预购」购买有时间限制，逾期将无法再购买。请守密人酌情购买。"
  },
