  Activity_68405_ActivityName = {
    Text = "神王复苏"
  },
  Activity_68405_ActivityPlot = {
    Text = "无尽渴求的祈愿中，祂于漫长的沉睡里短暂复苏，向这无趣的世界，投来真实的一瞥。\n永恒的生命里，这一瞥是如此短暂。"
