  Activity_68410_ActivityName = {
    Text = "雨镇幽影"
  },
  Activity_68410_ActivityPlot = {
    Text = "那场朦胧又潮湿的夜雨中，有一场注定的相逢在等待你。\n你记得她的名字，熟悉她的样貌， 那和缓而优雅的嗓音总让你如此安心。\n只是你忘了，乐于满足人类愿望的，从来只有神明与魔鬼。\n猜一猜，她属于哪一个？"
  },
  Activity_68410_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「魔女的宝库」"
  },
  Activity_68410_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「魔女小店」和「成就奖励」收集活动货币，活动货币可在「魔女的宝库」中用于交换从而获得道具奖励，包括活动限定SR命轮「魔女宽檐帽」、贤者之石、无垢之芯、流明之芯等。\n2、活动期间「特遣纪录：雨镇幽影」将免费开放，完成活动成就还能获得活动限定头像「以银钥之名：达芙黛尔」！。\n\n<Title:活动时间>\n1、2 月 24 日 9:00 - 3 月 10 日 9:00（GMT+8），所有活动内容均可参与。\n2、3 月 10 日 9:00 - 3 月 17 日 9:00（GMT+8），仅保留「魔女的宝库」和「成就奖励」，其他内容均已结束不可参与。\n\n<Title: 魔女小店>\n1、「魔女小店」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title: 活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「魔女小店」关卡任务报酬中的「苍白野兽头骨」、和「幽影野兽头骨」「殷红野兽头骨」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「达芙黛尔」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「至为珍贵的藏品」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「魔女宽檐帽」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title: 魔女的宝库>\n1、「魔女的宝库」共有三个，开启时间如下：\n·「解忧佳品」： 2 月 24 日 9:00 ~ 3 月 17 日 9:00。\n·「瑰丽秘宝」： 2 月 26 日 9:00 ~ 3 月 17 日 9:00。\n·「珍藏奇货」： 2 月 28 日 9 时 ~ 3 月 17 日 9:00。\n2、每次交换将消耗 750「苍白野兽头骨」/「幽影野兽头骨」/「殷红野兽头骨」，随机获得宝库中的五个物品奖励。\n3、每个宝库的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使指定物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 2 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 3 次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title: 特遣纪录>\n1、活动期间「特遣纪录：雨镇幽影」将免费开放。\n2、活动结束后，「特遣纪录：雨镇幽影」的调查进度会保留，如果活动期间未解锁「特遣纪录：雨镇幽影」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「特遣纪录：雨镇幽影」后都可以获得「钥令：灰雾真容」。"
  },
