  },
  Activity_71097_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_71098_ActivityName = {
    Text = "半步之隔·复刻"
  },
  Activity_71098_ActivityPlot = {
    Text = "她始终走在世人的前面。\n一步、两步，她的脚印引领着世人的步伐。\n可人们总是容易忘记，天才与疯子相隔不过半步。"
  },
  Activity_71098_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「师长的教诲」"
  },
  Activity_71098_ActivityTips = {
    Text = "<Title:活动简介>\n活动期间，守密人可通过限时玩法「虚无之门」和「成就奖励」收集活动货币「人偶零件」，「人偶零件」可在「师长的教诲」中换取奖励，包括活动限定SR命轮「牧羊人的手杖」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n\n<Title:虚无之门>\n1、「虚无之门」包含 9 个无需探索直接战斗的素材关卡，每天开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得培养素材和活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:人偶零件加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「虚无之门」关卡任务报酬中的「人偶零件」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「熔毁·朵尔」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「坠入虚无的人偶」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「牧羊人的手杖」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「人偶零件加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title: 师长的教诲>\n1、每次「交换零件」将消耗 750「人偶零件」，随机获得「师长的教诲」中的五个物品奖励。\n2、「师长的教诲」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 5 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 6 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动时间>\n1、6 月 16 日 9:00 - 6 月 30 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、6 月 30 日 9:00 - 7 月 7 日 9:00（GMT+8），仅保留「师长的教诲」和「成就奖励」，其他内容均已结束不可参与。\n3、7 月 7 日 9:00（GMT+8）后，剩余未兑换的「人偶零件」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
  Activity_71098_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_71100_ActivityName = {
    Text = "神王复苏"
  },
  Activity_71100_ActivityPlot = {
    Text = "无尽渴求的祈愿中，祂于漫长的沉睡里短暂复苏，向这无趣的世界，投来真实的一瞥。\n永恒的生命里，这一瞥是如此短暂。"
  },
  Activity_71100_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「觉知海渊」"
  },
  Activity_71100_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可以通过限时玩法「深海凝视」和「成就奖励」收集活动货币「惫倦绪思」、「悲愁绪思」、「欢悦绪思」。活动货币可在「觉知海渊」中购买商品，包括活动限定SR命轮「青石王座」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n2、活动期间，完成活动成就还能获得活动限定头像「以银钥之名：凯刻斯」、活动限定SR命轮「青石王座」、银芯和大量活动货币！\n\n<Title:活动时间>\n1、12 月 30 日 9:00 - 1 月 13 日 9:00（GMT+8），所有活动玩法均可参与。\n2、1 月 13 日 9:00 - 1 月 20 日 9:00（GMT+8），仅可参与「觉知海渊」和成就奖励。\n\n<Title:深海凝视>\n1、「深海凝视」有 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title:绪思加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「深海凝视」关卡任务报酬中的活动货币获得额外的掉落加成，具体加成如下：\n·唤醒体「图鲁」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「神王的颂歌」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「青石王座」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「绪思加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「绪思加成」影响。\n\n<Title: 觉知海渊>\n1、「觉知海渊」仅在 12 月 30 日 9:00 - 1 月 20 日 9:00（GMT+8）期间开放。\n2、1 月 20 日 9:00（GMT+8）后，剩余未兑换的「惫倦绪思」、「悲愁绪思」、「欢悦绪思」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
