  Activity_80312_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「疗养纪行」中领取奖励。\n2、「疗养纪行」永久开放。\n3、解锁「高级纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「高级纪行」仅在本活动生效。请守密人酌情理性消费。"
