  },
  Activity_81019_ActivityPlot = {
    Text = "是谁穿梭于梦幻的卡达斯，替主人清理垃圾？\n是珈伦~是珈伦！\n清理融蚀~梦境通风~维度消毒~把一切都打扫干净~\n毕竟在清扫方面，珈伦我可是专业的！\n主人要来试试么！珈伦会把清扫之法，毫无保留的教给主人的！"
  },
  Activity_81019_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过参与「扫除进度」并领取「清扫工具」。\n2、「清扫工具」积累到一定数量后可以在「除尘津贴」中领取丰富的奖励，包括活动限定头像「清理大师」、银芯、无垢之芯、贤石碎屑等。\n\n<Title: 扫除进度>\n1、「扫除进度」中包含了多个不同类型的清扫任务，守密人可以通过完成清扫任务来领取「清扫工具」，每日完成所有类型的清扫任务后还有一份额外的奖励！\n2、活动期间，每首次完成 1 种清扫任务就会播放隐藏剧情。\n3、「扫除进度」会在活动期间的每日 9:00（GMT+8）刷新重置。\n\n<Title: 除尘津贴>\n1、守密人累积「清扫工具」即可领取对应奖励，每达到 1000「清扫工具」可领取丰厚的物资奖励，累计达到 10000「清扫工具」可获得扫除奇旅专属头像「清理大师」。\n\n<Title:珈伦的谢礼>\n活动期间，可以在「珈伦的谢礼」处签到领取伽伦给守密人准备的谢礼！\n\n<Title:活动时间>\n本次活动仅在4 月 28 日 9:00 - 5 月 12 日 9:00（GMT+8）期间开放，5 月 12 日 9:00（GMT+8）后活动结束，请各位守密人记得领取「除尘津贴」中的奖励哦！"
  },
  Activity_81019_BannerText = {
    Text = "特别活动限时开启！"
  },
  Activity_81178_ActivityName = {
    Text = "于暴雨中摇曳"
  },
  Activity_81178_ActivityPlot = {
    Text = "骤雨从灰暗的天空中倾斜而下，将海面打得劈啪作响。\n无情的雷光肆意轰鸣，宣示着海面下无边恐怖的到来。\n辉煌的诺第留斯像蹒跚学步的婴儿，在波涛狂涌中脆弱地摇曳。\n无人知晓自己的命运将会如何，正如当无常的大海展示它的愤怒时，人们才得以明白，自己是何等渺小。"
  },
  Activity_81178_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「船员的秘宝」"
  },
  Activity_81178_ActivityTips = {
    Text = "<Title:活动简介>\n活动期间，守密人可通过限时玩法「邃海迷航」和「成就奖励」收集活动货币「信号旗」，「信号旗」可在「船员的秘宝」中换取奖励，包括活动限定SR命轮「海上领航者」、流明之芯、无垢之芯、贤石碎屑、拟态凝晶等。\n\n<Title:邃海迷航>\n1、「邃海迷航」包含 9 个无需探索直接战斗的素材关卡，每天开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得培养素材和活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地通关。\n\n<Title:信号旗加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「邃海迷航」关卡任务报酬中的「信号旗」获得额外的掉落加成（包括重现），具体加成如下：\n·唤醒体「克珀珊特」：启灵0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命轮「圣火中的指引」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命轮「海上领航者」：叠位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同唤醒体或命轮的「信号旗加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到上述加成影响。\n\n<Title: 船员的秘宝>\n1、每次「交付旗帜」将消耗 750「信号旗」，随机获得「船员的秘宝」中的五个物品奖励。\n2、「船员的秘宝」的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前 5 次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第 6 次及之后重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动时间>\n1、5 月 5 日 9:00 - 5 月 19 日 9:00（GMT+8），活动简介中的所有内容均可参与。\n2、5 月 19 日 9:00 - 5 月 26 日 9:00（GMT+8），仅保留「船员的秘宝」和「成就奖励」，其他内容均已结束不可参与。\n3、5 月 26 日 9:00（GMT+8）后，剩余未兑换的「信号旗」将按照每个兑换「蔷薇金券」× 40 的比例进行回收，请守密人注意查收邮件。"
  },
  Activity_81178_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_81179_ActivityName = {
    Text = "最后的引航"
  },
  Activity_81771_ActivityName = {
    Text = "窥觑神国的阴影"
  },
  Activity_81771_ActivityPlot = {
    Text = "无人窥见神国的圣辉，但从那偶然泄露的真相里，人们能够感知到神国的阴影。\n它就在那里，一直在那里，而无数的虔诚者会让它真正降临。\n无论要犯下怎样深重的罪孽作为代价。"
  },
  Activity_81771_ActivityStageEndContent = {
    Text = "活动已结束"
  },
  Activity_81771_ActivityTips = {
    Text = "<Title: 异动海潮>\n·「异动海潮」包含 7 个关卡，活动首日开放前 3 个，之后每 3 天开放 1 个。每个关卡都有不同的丰厚奖励！\n·每种「异动海潮」均有大量集群，每当某个种类的集群被任何守密人挑战胜利时，该类型「异动海潮」的集群数量就会减少 1，当该类型异动海潮的所有集群被消灭后，相应的关卡就会关闭，无法再次挑战。\n·每位守密人每天最多可以击退 20 次「异动海潮」集群，活动持续期间每日 9:00（GMT+8）重置次数。\n·每个关卡会提供不同的造物，将会为你提供强大的加成。\n·所有关卡必须选择助战，整个活动中，每个互相关注的守密人只能为你提供一次助战。\n·守密人需要至少完成调查行动 2-9 才可以参与该活动。\n\n<Title: 等级补偿>\n·在「窥觑神国的阴影：异动海潮」中有等级补偿机制，以便各位守密人能够共同抵御入侵！\n等级补偿规则如下：\n ·调查队伍中，等级不足 60 级的唤醒体在本次挑战中将会补偿至 60 级。\n·调查队伍中，技能等级不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n·调查队伍中，「疯狂预兆」不足 6 级的唤醒体在本次挑战中将会补偿至 6 级。\n·调查队伍中，「灵塑适性」不足 5 级的唤醒体在本次挑战中将会补偿至 5 级。\n ·若守密人等级不足60级，在本次挑战中将会补偿至60级。\n\n<Title:限时任务>\n·活动期间，累计击退 30 次异动海潮即可完成限时任务，获得「简易幻衣绘形券（一期）」×1！\n·在5 月 26 日 9:00 - 6 月 9 日 9:00（GMT+8）期间，可以在「商店：幻衣订购」使用「简易幻衣绘形券（一期）」兑换简约幻衣。\n·更多获取「简易幻衣绘形券（一期）」的方式可在社区和公告中了解。"
  },
