  Activity_84175_ActivityName = {
    Text = "复律纪行"
  },
  Activity_84175_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「复律纪行」中领取奖励。\n2·任务分为多组，在活动开启后每日解锁一组。\n3、解锁「复律纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「复律纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_84176_ActivityName = {
    Text = "时绁纪行"
  },
  Activity_84176_ActivityTips = {
    Text = "活动规则：\n1、守密人完成指定的纪行任务后，可以在「时绁纪行」中领取奖励。\n2·任务分为多组，在活动开启后每日解锁一组。\n3、解锁「时绁纪行」后，完成任务后可额外领取奖励。\n4、请注意：在本活动中解锁的「时绁纪行」仅在本活动生效。请守密人酌情理性消费。"
  },
  Activity_89008_ActivityName = {
    Text = "萦回维度的追随"
  },
  Activity_89008_ActivityPlot = {
    Text = "她穿行过无数的维度、无数的世界，经历过无数的希望与绝望，但她不会停下脚步。因为，她明确知晓自己目的地——有你的地方。"
  },
  Activity_89008_ActivityTips = {
    Text = "<Title:简介>\n1、活动期间，守密人每天登录后可以在「萦回维度的追随」中领取当日签到奖励。\n2、奖励将根据守密人累计登录依次解锁，当日签到奖励将在9点（GMT+8）刷新。\n\n<Title:限时任务>\n·活动期间，累计登录 7 天即可完成限时任务，获得「简易幻衣绘形券（一期）」×1！\n·在5 月 26 日 9:00 - 6 月 9 日 9:00（GMT+8）期间，可以在「商店：幻衣订购」使用「简易幻衣绘形券（一期）」兑换简约幻衣。\n·更多获取「简易幻衣绘形券（一期）」的方式可在社区和公告中了解。"
  },
  Activity_89008_BannerText = {
    Text = "签到领取超多无垢之芯"
  },
  Activity_89576_ActivityName = {
    Text = "愿希望再度萌芽"
  },
  Activity_89576_ActivityPlot = {
    Text = "每日登录可领取纪念限定SSR命轮「重生于湮土」，总计可领取16个！"
  },
  Activity_89576_ActivityTips = {
    Text = "<Title:简介>\n世界在崩毁。在这样的世界里，绝望是常态，痛苦是常态。我必须习惯。但是……仍有温暖蛰伏于我的心脏，等待着破胸而出。\n\n<Title:活动规则>\n·活动期间，守密人每天登录后可以在「愿希望再度萌芽」中领取纪念限定 SSR 命轮「重生于湮土」，总计可领取 16 次。\n·奖励将根据守密人累计登录依次解锁，当日登录奖励将在9点（GMT+8）刷新。"
  },
  Activity_89576_BannerText = {
    Text = "限定SSR命轮免费领取"
  },
  Activity_89729_ActivityName = {
    Text = "支线关卡免费解锁"
  },
  Activity_89730_ActivityName = {
    Text = "镜像囚徒"
  },
  Activity_89730_ActivityPlot = {
    Text = "飞鸟啊飞鸟，你的脚上为何有断裂的镣铐？\n飞鸟啊飞鸟，你为何在高空之上孤独地鸣叫？\n挣脱荆棘、逃离囚笼，你展翅飞过了漫漫黄沙，只是你悲伤的鸣叫不曾停止。究竟何人，才是你寻找的忠诚旅伴？究竟何处，才是你寻找的真正家乡？"
  },
  Activity_89730_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「求知的愿望」"
  },
  Activity_89730_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「飞跃青空」、「梦境巡梭」和「成就奖励」收集活动货币「常识之书」、「数理之书」、「文学之书」，「常识之书」、「数理之书」、「文学之书」可在「求知的愿望」中购买商品，包括活动限定SR命轮「孤羽」、流明之芯、无垢之芯等。\n2、活动期间，「异梦视界：天边之外·上」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：卡斯托尔」！\n\n<Title:活动时间>\n1、6 月 2 日 9:00 - 6 月 16 日 9:00（GMT+8），所有活动玩法均可参与。\n2、6 月 16 日 9:00 - 6 月 23 日 9:00（GMT+8），仅可参与「求知的愿望」和成就奖励。\n\n<Title:飞跃青空>\n1、「飞跃青空」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 求知的愿望>\n「求知的愿望」共有三个商店，开启时间如下：\n·「通识选修课」： 6 月 2 日 9 时开启。\n·「科学选修课」： 6 月 4 日 9 时开启。\n·「文学选修课」： 6 月 6 日 9 时开启。\n在商店内可以选择商品直接进行购买。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「飞跃青空」关卡任务报酬中的「常识之书」、「数理之书」、「文学之书」获得额外的掉落加成，具体加成如下：\n·唤醒体「卡斯托尔」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「不可承受的自由」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「孤羽」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title: 梦境巡梭>\n1、每小时自动获得 60「常识之书」，最多储存 25 小时。\n\n<Title:异梦视界>\n1、活动期间，「异梦视界：天边之外·上」可免费解锁。\n2、活动结束后，「异梦视界：天边之外·上」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「异梦视界：天边之外·上」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：天边之外·上」后都可以获得「钥令：错位命运」。"
  },
  Activity_89730_BannerText = {
    Text = "玩法活动限时开启！"
  },
  Activity_89899_ActivityName = {
    Text = "幻衣缝制"
  },
  Activity_89899_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可使用「幻视单片镜」进行抽取。每次抽取所需要的「幻视单片镜」数量会增加。\n2、银枢幻衣有机会从第5次抽取开始获得。完成10次抽取必定获得当期银枢幻衣。\n3、活动结束后若有剩余「幻视单片镜」将自动转化为源液。"
  },
  Activity_89899_BannerText = {
    Text = "抽奖活动限时开启！"
  },
  Activity_90052_ActivityName = {
    Text = "腐坏之脑"
