  Activity_96838_ActivityName = {
    Text = "画布的暗面"
  },
  Activity_96838_ActivityPlot = {
    Text = "一场色彩的核爆，一次形式的狂乱。\n近乎正常的画卷，被鲜血的笔触涂抹，\n刮刀之下，亡魂在画布的暗面颤栗低语。\n最真实、最完美的艺术就潜藏在疯癫与荒诞背后，\n唯有撕裂表象的疯狂，方能窥见世界的里侧。"
  },
  Activity_96838_ActivityStageEndContent = {
    Text = "活动已结束，当前仅可参与「皮克曼的画室」"
  },
  Activity_96838_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「异界图卷」、和「成就奖励」收集活动货币「真实之染」、「幻梦之染」、「癫狂之染」，「真实之染」、「幻梦之染」、「癫狂之染」可在「皮克曼的画室」中购买商品，包括活动限定SR命轮「渴求的画笔」、流明之芯、无垢之芯等。\n2、活动期间，「意识潜游：畸世绘」限时免费解锁，完成活动成就还能获得活动限定头像「以银钥之名：皮克曼」！\n\n<Title:活动时间>\n1、9 月 8 日 9:00 - 9 月 22 日 9:00（GMT+8），所有活动玩法均可参与。\n2、9 月 22 日 9:00 - 9 月 29 日 9:00（GMT+8），仅可参与「皮克曼的画室」和成就奖励。\n\n<Title:异界图卷>\n1、「异界图卷」包含 7 个关卡，每 1 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title: 皮克曼的画室>\n1、「皮克曼的画室」共有三个商店，开启时间如下：\n·「真实画室」： 9 月 8 日 9 时开启。\n·「幻梦画室」： 9 月 10 日 9 时开启。\n·「癫狂画室」： 9 月 12 日 9 时开启。\n2、每次交换将消耗 750「真实之染」/「幻梦之染」/「癫狂之染」，随机获得画室中的五个物品奖励。\n3、每个画室的物品奖励分为「特殊物品」和「普通物品」两种，重置时可以使特殊物品奖励的剩余数量重置至上限，具体规则为：\n（1）前2次重置：当「特殊物品」无剩余数量后，守密人可以选择重置，重置后会将「特殊物品」和「普通物品」的剩余数量重置至上限；也可以选择继续交换，当「普通物品」也无剩余数量后，须进行重置才可以继续交换。\n（2）第3次开始重置：当「普通物品」无剩余数量后才可以进行重置，重置会将「普通物品」的剩余数量重置至上限，「特殊物品」不再重置。\n\n<Title:活动加成>\n1、守密人拥有特定唤醒体或命轮（不要求上阵）可以使「异界图卷」关卡任务报酬中的「真实之染」、「幻梦之染」、「癫狂之染」获得额外的掉落加成，具体加成如下：\n·唤醒体「皮克曼」：启灵0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命轮「写实主义悖谬」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命轮「渴求的画笔」：叠位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同唤醒体或命轮的「活动加成」以叠加的方式结算。 \n3、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title:意识潜游>\n1、活动期间，「意识潜游：畸世绘」可免费解锁。\n2、活动结束后，「意识潜游：畸世绘」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「意识潜游：畸世绘」，活动结束后仍然可以消耗「现实起点」×3解锁。\n3、无论是否在活动期间，通关「意识潜游：畸世绘」后都可以获得「钥令：虚世之彩」。"
  },
