  Activity_97853_ActivityPlot = {
    Text = "你曾幻想过，如果灾难不曾来临，所有人的生活究竟会是什么样子。\n你拯救世界的力量没有了用武之地， 每天都要为平凡的校园生活和赚取可怜的学分奔波。操场上再也没有了训练作战的身影，取而代之的是一排排社团活动的帆布棚子，与招揽、嬉闹的叫嚷声；待放学的钟声敲响，饥饿的学生们便立刻挤满了食堂……\n敲开你牵挂着的人们的房门，你会看到怎样的笑脸？"
