  Activity_97853_ActivityTips = {
    Text = "<Title:活动简介>\n1、活动期间，守密人可通过限时玩法「日光下新事」收集活动货币「海滨特产贝壳」，「海滨特产贝壳」可在「学生会办公楼」中购买商品，包括流明之芯、无垢之芯、贤石碎屑等。\n2、活动期间，「异梦视界：再见，永无乡」限时免费解锁！\n\n<Title:活动时间>\n1、10 月 6 日 9:00 - 10 月 20 日 9:00（GMT+8），所有活动玩法均可参与。\n2、10 月 20 日 9:00 - 10 月 27 日 9:00（GMT+8），仅可参与「学生会办公楼」和成就奖励。\n\n<Title:日光下新事>\n1、「日光下新事」包含 5 个关卡，每 2 天自动开放 1 个。\n2、每次挑战将消耗 「灵啡肽」× 120 ，挑战成功将获得活动货币。\n3、关卡通关后，解锁该关卡的「重现」功能。请注意：使用「重现」功能时，无法获得同调率。\n4、可以使用校友会助战来帮助你更轻松地过关。\n\n<Title:活动加成>\n1、解锁「假日纪行」中的「高级纪行」，可在「日光下新事」关卡报酬中获得额外100%的「海滨特产贝壳」掉落（包括重现）。\n2、特别的，癫狂难度首通挑战奖励不会受到「活动加成」影响。\n\n<Title: 学生会办公楼>\n「学生会办公楼」共有一个商店， 10 月 6 日 9 时开启。\n在商店内可以选择商品直接进行购买。\n\n<Title:异梦视界>\n1、活动期间，「异梦视界：再见，永无乡」可免费解锁。\n2、活动结束后，「异梦视界：再见，永无乡」的调查进度会保留，完成活动期间未完成的调查事件后也可以获得与活动期间一致的调查奖励。如果活动期间未解锁「异梦视界：再见，永无乡」，活动结束后仍然可以消耗「现实起点」×7解锁。\n3、无论是否在活动期间，通关「异梦视界：再见，永无乡」后都可以获得「钥令：美梦一刹」。"
